-- Generated source references; not native quest records.
local addon = WordHunterWoW_Addon
local compat = addon and addon.Compat
local flavor = compat and compat.GameFlavor and compat.GameFlavor()
if not (flavor == "retail") then return end
local pack = WordHunterWoW_QuestSources and WordHunterWoW_QuestSources["multilanguage-retail"]
if not pack then return end
pack.loaded = true
local quests = pack.locales.enUS

quests[27733] = { id = 27733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Good Ol' Switcheroo", description = "Look, I'd love to give the order and have my men blast these rebels to bits right now, but I can't because the entire Stockade is under Warden Thelwater's jurisdiction, and he only wants to contain them right now.\n\nRather than disobey orders, we're going to take care of this in a slightly different manner! We've managed to befriend Mortimer Moloch, who just so happens to be the ruthless rebel leader Randolph Moloch's twin. Kill Randolph, and we'll switch 'em so Mortimer can stop the rebellion peacefully!", progress = "We can't make the switch until Randolph is dead!", completion = "Yes, Mortimer just faked his own death. He'll probably take on his brother's name and continue on his 'epic schemes'. We'll just have to deal with that when the time comes.", objectives = "Kill Randolph Moloch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27737] = { id = 27737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "By Fire Be Saved!", description = "I'm well-versed in first aid and other forms of healing, and with the help of my Lightwell I've been able to nurse many of our men back to full health. The problem we still have is that it's so cold and damp down here that I'm losing them anyways, despite healing their wounds!\n\nThe quakes angered the elements that reside in the prison...when they erupted out of the earth they slaughtered half of the prisoners. If you slay their leader, Lord Overheat, and bring me his core I can use it to warm our men!", progress = "Do you have the core? Our men are dying in here!", completion = "Thank goodness! With this fire, our men will live through this ordeal!\n\nThank you so much, hero.", objectives = "Obtain Lord Overheat's Fiery Core.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27738] = { id = 27738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pit of Scales", description = "A spot on the southern end of the map was marked with hieroglyphs of crocodiles fighting each other.\n\nThat must be where Caimas took Tahet.\n\nGo to the Pit of Scales and find a way to rescue the Vizier's son.", completion = "I thank you for what you've done, {name}.  You can count on my vote when High Council convenes.", objectives = "Rescue Tahet at the Pit of Scales in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27739] = { id = 27739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gnoll King", description = "{name}, I'm afraid I must ask of you the impossible.\n\nI received my eyepatch because he willed it so. Countless thousands have perished to his wrath. It was only by sheer miracle that we were able to imprison him here.\n\nDoing so was a grave mistake. We held out as long as we could, but then they came. From the shadows and darkness, gnolls in service of Hogger ripped my best men to pieces.\n\nYou must defeat the Gnoll King, lest he mounts another attack and slaughters us all in cold, bloodthirsty rage.", progress = "Have you defeated Hogger?", completion = "You have performed a deed this day unlike any I have seen in my long career. Hogger's death will plague the Riverpaw for years to come, and hopefully put an end to their attacks on our people.\n\nGreatest of heroes, please take this as a sign of my eternal gratitude.", objectives = "Defeat Hogger.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27740] = { id = 27740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baba Bogbrew", description = "Hey, while you were out, the Baron stopped by! He kicked me until money came out!\n\nHe always does that though. But this time he asked me to tell you something! He wants you to go south and help out our herbalist, Baba Bogbrew.\n\nShe's all the way across the water! But just talk to my girl Daisy outside and she'll send you there the Crazy Larry way!", completion = "Ah, it's so nice to have help dropped in.\n\nModern convenience... I can't get enough of it.", objectives = "Talk to Lil' Crazy Daisy to take a cannon ride to Baba Bogbrew.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27741] = { id = 27741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Show Me Your Papers", description = "After your work in dealing with the Twilight's Hammer cult, Captain Anton recommended you for a delicate assignment.\n\nMy men recently discovered a group of cultists attempting to sneak into the city. The flow of traffic into the Stormwind has come to a halt. The king has decreed that all visitors must be searched before they can enter the gates. Take this copy of his proclamation and read it to the people assembled at the front gates, then assist the guards there in searching those who wish to enter.", completion = "So there were more cultists waiting to be admitted to the city? It's a good thing that you caught them, {name}. Reading over the note that you found, it seems they're planning something big.", objectives = "Go to the front gates of Stormwind, read King Wrynn's Proclamation and search 5 Stormwind Citizens. Keep anything suspicious that you find.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27742] = { id = 27742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little on the Side", description = "You know, it's our moral obligation to save all of this Elementium from the shale spiders. Those creepy things eat the stuff!\n\nWhat a waste!\n\nSo, what do you say? 90/10 my way?", progress = "How much do you think you can carry?", completion = "<Goldmine slyly looks at the pile of Elementium shards.>\n\nHmm, I don't think that stuff's going to sell for much. I better give you your cut right now so you don't feel ripped off.", objectives = "Collect 6 Elementium Shards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27743] = { id = 27743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "While We're Here", description = "You know, while we're here, we might as well take care of the Twilight's Hammer intruders. This place used to be ours, after all!\n\nI'd help, but with my totems and weapons broken, I'm pretty helpless.", completion = "They had it coming to them.", objectives = "Slay 12 Twilight's Hammer cultists, either Depths Overseer or Twilight Miners, within the Elementium Depths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27744] = { id = 27744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rune Ruination", description = "Examining the Twilight Rune of Earth, you can almost feel its power extending further into the Elementium Depths.\n\nIt's probably connected to other runes. Initiate Goldmine thinks that you should destroy all of them.", progress = "We still have some runes to destroy, {name}.", completion = "That'll teach 'em to move in on our territory!\n\nWhat's that over across the way?", objectives = "Destroy the Twilight Rune of Earth, Rune of Water, Rune of Air, and Rune of Fire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27745] = { id = 27745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fiery Reunion", description = "That's Magmatooth, my estranged fire elemental. {name}, you gotta kill him or he's gonna kill me!\n\nIt was all just a big misunderstanding. How was I to know he'd be mad about me \"borrowing\" his heart down in Deepholm? He can't die... not permanently anyway!\n\nHe's got the controller to the portal on him for sure. You gotta get the controller and then use it in the Fire portal to take us back to the entrance.", progress = "{name}!", completion = "We survived and all of the portals are now shutdown!\n\nYou don't think Magmatooth is going to hold a grudge, do you?", objectives = "Obtain the Fire Portal Controller and use it at the Fire Portal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27746] = { id = 27746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Empire of Dirt", description = "This war has taken its toll on us as a people. We have lost much to secure our place as the rightful rulers of Lordaeron. And though the moment is won, the battle continues to rage in other parts of the Eastern Kingdoms.\n\nI must return to the Undercity to recuperate. I want you to go to Hillsbrad Foothills in my stead, {name}. As my most trusted soldier, you will lead our forces to absolute domination against our enemies in Hillsbrad.\n\nReport to High Executor Darthalia at Southpoint Blockade, to the east.", completion = "News of your conquest in Silverpine emboldens us, {name}. We are prepared to fight at your command and beat back the last remaining vestiges of humanity in Hillsbrad.", objectives = "Report to High Executor Darthalia at Southpoint Blockade in Hillsbrad Foothills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27747] = { id = 27747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Total War", description = "Many of the Wildhammer have already fled their homes. It is time to wipe them from the map.\n\nUp on the ridge to the north you will find abandoned houses in the Thundermar Ruins. Kegs of potent Thundermar ale have been left behind.\n\nThundermar ale is 220 proof; I don't know how that's possible.\n\nSmash open the kegs and set their content aflame. Burn them out! Leave the dwarves nothing to return to!", completion = "Yes, yes. Burn them out, as you would flush groundhogs from their holes...\n\nWell done, {name}.", objectives = "Smash 10 Thundermar Ale Kegs within the Thundermar Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27748] = { id = 27748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortune and Glory", description = "We have to keep moving, {name}. It's just a matter of time before those troops get their act together.\n\nThe coffer should be just beyond these ruins.\n\nStay on your toes. Something tells me this isn't over yet...", completion = "Good to see you're still in one piece, {name}.", objectives = "Kill the Obsidian Colossus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27749] = { id = 27749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arrest the Infiltrators", description = "You were right to bring this note to me, {name}. The king's proclamation came too late; they already have infiltrators at work in the city.\n\nThis note contains instructions and locations for cultists to meet, but it doesn't say what they're doing. Our enemies have grown smarter. It's going to be tough to track down all the infiltrators, but we have to get as many as we can. Use these cuffs to restrain any agents you find, bring them to the entrance of the Stockade, and report to me when you're finished.", completion = "Excellent work, {name}. The note you captured makes sense in light of this ritual the infiltrators mentioned. This city is infested with cultists and their sympathizers. We must act before their plans can come to fruition.", objectives = "Use the Heavy Manacles to arrest 5 Cultist Infiltrators and bring them to Warden Thelwater at the Stockade. After you've returned with your prisoners, question one of the Detained Cultists in the Stockade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27750] = { id = 27750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War Forage", description = "<Griff's stomach growls.>\n\nWhenever we Dragonmaw go on the warpath, everyone stops hunting.\n\nThe best tasting food is stolen from the mouths of the enemy. Up on the ridge north of the river there's a bunch of wrecked Wildhammer houses. I bet they're loaded with food.\n\nBring some to my mouth.", progress = "Hungry.", completion = "<Griff greedily snatches the heap of food, enough to feed dozens of men.>\n\nGreat! Did you get any for yourself?", objectives = "Gather 10 Wildhammer Food Stores from the Thundermar Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27751] = { id = 27751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Wildhammer", description = "Since my people first claimed the Highlands, the Wildhammer dwarves have been our persistent foe. We fought them in Grim Batol, we fought them in the Wetlands, and even now open warfare rages to our north, across the river, amidst the Thundermar Ruins.\n\nProve your valor to me. Seek out and crush Wildhammer Warbrands. The best among them carry insignias - my warriors collect them by the dozen.\n\nCan you?", progress = "Show me the insignias you've collected, {class}.", completion = "<Narkrall clenches the insignias in his weathered hand.>\n\nSo, {class}. There's more to you than meets the eye.\n\nMaybe your Horde can stand with the best of my warriors. Let's try you out...", objectives = "Kill Wildhammer Warbrands to collect 8 Wildhammer Insignias. Named characters within the Thundermar Ruins will also carry insignias.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27752] = { id = 27752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fight Like a Wildhammer", description = "S'not a boast to say that we Thundermars brew the finest ale in the Eastern Kingdoms. It's 220 proof. Yeah, you heard me!\n\nAs folks fled from the south to the town center, they were forced to leave behind their ale.\n\n<Blundy pauses, allowing the gravity of the situation to soak in.>\n\nGET IT BACK! That stuff'll turn even the stringiest of warriors into a whirlin' dervish of mouth-foaming destruction. Get them kegs! S'our only hope!", progress = "Get me that ale, {name}.\n\nHey, you haven't been skimmin' off the top, have you?", completion = "Oh aye ... we get a few of these kegs out to the boys on the front and we're gonna see some fireworks. Thank you, {name}!", objectives = "Collect 10 Kegs of Thundermar Ale from the Thundermar Ruins. Careful - it's got some kick!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27753] = { id = 27753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Never Leave a Dinner Behind", description = "Supplies are short, {name}. We've got refugees coming into Thundermar from up and down the ridge - that's a lot of mouths to feed.\n\nPlenty of food stores were left behind as people pulled their families to safety. We need that food!\n\nScour the Thundermar ruins south, east, and southwest of here for food stores.\n\nCareful, {class}! The fighting around the ruins is pretty intense.", progress = "Got some eats?", completion = "It's good - hardly a worm or weevil to be found!\n\nThis is a lifesaver to the folk who fled here for survival.", objectives = "Gather 10 Wildhammer Food Stores from the Thundermar Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27754] = { id = 27754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonmaw Takedown", description = "The Dragonmaw!\n\n<Colin spits.>\n\nMonsters, all of them. We've fought them up and down these highlands since the last war. And now they're joining forces with the Horde?\n\nIf you're going to convince us Wildhammers to unite under the Alliance banner, you'd best prove yourself against the Dragonmaw. Wade into the battle that's raging in the Thundermar ruins to the south and southwest. Kill Dragonmaw marauders and collect the insignias that their greatest warriors wear. Then we'll talk.", progress = "How goes the fight, {class}?", completion = "Look at that! That's quite a collection of trophies you have there.\n\nI'll spread the word. If a single Alliance {class} can do this, imagine what the rest of your lot can accomplish!", objectives = "Kill Dragonmaw Marauders and collect 8 Dragonmaw Insignias. Named characters within the Thundermar Ruins will also carry insignias.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27755] = { id = 27755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Curse of the Tombs", description = "The Neferset are not the only threat to our sacred tombs.\n\nA gnomish expedition stumbled upon our lands a few weeks ago.\n\nThey did not heed our warnings and dug too deep within a cursed vault.\n\nTheir entire expedition is now afflicted by a terrible curse that has robbed them of their sanity and taken control of their minds.\n\nThey now seek access to the deepest vaults of Uldum and pose a great threat. \n\nGo to the Sunstone Terrace and put their wretched souls out of their misery.", completion = "They couldn't be saved, {name}.  The ancient curse that fell upon them is irrevocable.", objectives = "Slay 6 Crazed Diggers and Mekgineer Mixeltweed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27756] = { id = 27756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Foreman", description = "If we're to find out what's going on down here it looks like we're going to have to fight our way through the entire Deadmines! Glubtok the Foreman will be the first major foe you encounter, a powerful ogre magi. Be careful, he possesses the brute strength of his race backed by his wicked spellcasting!\n\nTake this communicator so that I can keep in touch with you as we continue our investigation. Be careful down there.", progress = "Yes?", completion = "<Bzzzzzzzzzzzzt.>\n\nNicely done! A clean kill. Now continue on and see what else you can find! We'll crack this case wide open with you on our side, I just know it.", objectives = "Kill Glubtok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27757] = { id = 27757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Darkest Depths", description = "I've been seeing sea creatures acting oddly through the whole swamp. The murlocs, yes, but before that the gilblins, and the makrura... I even saw some naga wander ashore the other day.\n\nSomething's calling them here, and working them into a frenzy to boot. Many of the creatures have been drawn to Stagalbog Cavern to the west. Something's down there, and if it gets any stronger we'll all start wandering in there too...\n\nYou should put a stop to whatever it is before that happens.", completion = "Oh my. It sounds like you ran across quite a sinister being. I wonder what one of those was doing all the way out here...", objectives = "Slay Hr'nglth the Lost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27758] = { id = 27758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Carpenter", description = "<Bzzzzzzzzzzzzt.>\n\nHello, can you hear me? Excellent!\n\nIt looks like Helix is in charge of building an enormous mast. You don't think they're trying to finish the Defias Juggernaut, do you?\n\nYou'd better go investigate {name}, and don't be afraid to get your hands dirty! You have clearance to use deadly force if necessary and, let's face it, it's probably going to be necessary.", progress = "Yes?", completion = "<Bzzzzzzzzzzzzt.>\n\nHey, it's Horatio. That was intense! I'm watching your progress on the Stormwind Communicator's Spyatron X3 application.\n\nThey sure are using a lot of heavily fortified doors to hide their work. Keep pushing forward and see what you find next. I bet it'll be a huge clue!", objectives = "Defeat Helix Gearbreaker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27760] = { id = 27760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artificial Intelligence", description = "<A feminine voice addresses you over the portable terminal.>\n\nEmergency code: 55-729.\n\nUpper cerebral cortex functions in expedition members have been compromised.\n\nPlease report to your nearest terminal location, to the southeast of the Sunstone Terrace, for further analysis.", progress = "<The terminal whirrs as its mechanisms become active.>", completion = "Scanning subject...\n\nCerebral cortex diagnostics indicate the absence of \"tomb curse\" phenomenon.\n\nDiagnostics did reveal frequent head trauma.  The user would do well to exercise more caution around blunt objects in the future.", objectives = "Speak to the A.I.D.A. terminal at the Surveyor's Outpost  in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27761] = { id = 27761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Disarming Distraction", description = "The curse has taken over the expedition members' higher brain functions, but my calculations reveal their suppressed adolescent subconscious can still be stimulated by realistic imagery.\n\nUtilize this holo-projector to distract them.\n\nThey are currently setting up explosives at the tomb to the east to attempt to gain access to secret passages in Uldum.\n\nThey seek dangerous re-origination technology beneath Uldum and must be stopped.", progress = "Greetings, user {name}.  I am happy to see you are still unaffected by the effects of the expedition curse.", completion = "Well done, {name}.  The expedition has already doomed itself.\n\nThere is no need for it to endanger the rest of the world as well.", objectives = "Disarm the First, Second and Third Bomb Clusters and deactivate 4 Unstable Bomb Bots at the Tomb of the Sun King.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27762] = { id = 27762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fuselight, Ho!", description = "Hey, {race}, listen up.  I got a job opportunity that you aren't gonna want to miss out on.\n\nWe been sent up here from Fuselight, a new goblin town way down in the Badlands.  Lots of money to be had down there, yes <sir/ma'am>.  And not nearly so many zombies... or uptight Argent paladin-types.\n\nNope, it's an untamed wilderness down there, and we're looking for someone like you to help us tame it.  Whenever you're ready... we'll be waiting.", completion = "Nice landing!", objectives = "Ride The Uncrashable to the Badlands, then report to Eddie Flofizzle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27763] = { id = 27763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Fuselight Proper", description = "This, {race}, is paradise.  I've always wanted to live in a nice quiet town by the sea so I can focus on my explosions without any distractions.\n\nQuiet's not for everybody, though... 'specially the adventuring hero-type, like yourself.\n\nWe've installed a teleporter in the backside of town that'll take you up to the top of the cliffs.  From there, you can take the quick ride west into Fuselight proper, within the Badlands.\n\nThere should be more for you to do up there.  Tell 'em that Flo sent you.", completion = "Welcome to Fuselight!", objectives = "Use the Teleporter in the back of Fuselight-by-the-Sea to port up the mountain, then report to Dolph Blastus at Fuselight in the Badlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27764] = { id = 27764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Strange Request", description = "On to other matters.  I have a package that I need delivered.\n\nA young lady came by our town not long ago, looking for compressed blasting powder, a tempered mithril bomb casing, and some safety goggles.  Naturally, we had plenty of blasting powder and bomb casings to sell her, but the safety goggles were a little harder to find.\n\nLong story short, I've got the goggles, but she's already returned to her studies down in Lethlor Ravine.  Will you bring these down to her?", progress = "Ahh... you've found me.  Good.", completion = "Thank you, {race}.  You may keep the goggles, as they have already served their purpose: they brought you to me.", objectives = "Bring Dolph's Package to Rhea at Lethlor Ravine in the Badlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27765] = { id = 27765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Sample: Wild Eggs", description = "I am experimenting with black dragons.  Specifically, I am interested in how they procreate.\n\nMy current experiments require plenty of black dragon eggs, which is why I am here in Lethlor Ravine.  I'd gather the eggs myself, but I think you'll benefit from helping me out.\n\nYou will find them along the edges of the ravine.  Beware the guardians that circle above - they do not appreciate stolen eggs.", progress = "Have you brought the eggs?", completion = "Thank you for gathering these so quickly, {name}.", objectives = "Obtain 6 Wild Black Dragon Eggs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27766] = { id = 27766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Second Sample: Whelps", description = "I need another favor from you.  I need you to obtain the bodies of the black dragon whelplings that fly nearby.  Slay them, and bring the corpses to me.", progress = "Have you done as I asked?", completion = "This grisly task was necessary, {name}.\n\nAll will be revealed to you soon.  For now, know this:\n\nI am no ordinary goblin.\n\nI serve a mistress of unimaginable power, and her motives here are not as dark as they might seem.", objectives = "Obtain 10 Scalding Whelp Corpses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27767] = { id = 27767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back Under Cover", description = "The cultists seem assured of their victory, even as we detain more and more of them. We must find out more about the ritual mentioned by the cultist you questioned.\n\nThese rituals seem to be the core of the cult's plan to attack Stormwind. I'm going to give you one of the robes taken from the arrested cultists. Put it on and go back to the cultist outpost at Mirror Lake Orchard in Elwynn Forest and see if you can get the cultists there to let you in on the plan.", progress = "It's good to see you again, {name}. We were worried that the tyrant Wrynn's guards had thrown you into the Stockade.", completion = "You need to familiarize yourself with the portal ritual quickly. We need to send as many teams into Stormwind as we can. They're discovering and arresting more of our brothers each day.", objectives = "Put on your Recruit's Robe, go to Mirror Lake Orchard and get the Book of Incantations from Overseer Sylandra. Read from the Book of Incantations near the Cultist Altar to practice the ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27768] = { id = 27768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Step Two: The Bloodletter", description = "The trolls here perpetuate the fall of my brethren to the nightmare. They infect and corrupt green dragons with the blood of their foul god, and then harvest the evil that has grown within them. They are being farmed like livestock...\n\nThis disgusting savagery cannot continue. Return to where you left the Hall of Masks and take the other corridor towards the Butchery. Gomora the Bloodletter harvests corpses for these foul and evil rituals there. Take his undeserved life from him!", objectives = "Slay Gomora the Bloodletter in the Butchery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27769] = { id = 27769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rhea Revealed", description = "As I hinted earlier, I am no ordinary goblin.  You may have already guessed my true identity.\n\nAllow me to show you my true form.  As you have proven yourself trustworthy, I will also share with you the details of my plan.", progress = "You are certainly impatient, {name}.", completion = "My true name is Rheastrasza, and I am an envoy of Alexstrasza herself, the Aspect of the red dragonflight.\n\nWith Deathwing currently occupied with other matters, we are going to find a way to redeem the black dragonflight.\n\nAnd you are going to help us.", objectives = "Learn Rhea's true identity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27770] = { id = 27770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lifting the Veil", description = "The black dragonflight was once noble.  They were the earth warders, protecting the very land itself.  How ironic that they would become the worst menace the land has known.\n\nI believe that there remains a sliver of hope, however, and so does my mistress.  The black dragonflight will live beyond Deathwing's treachery, and will soar as the noble earth warders once again.\n\nI wish to show you something.  Close your eyes, and I will reveal to you the final part of my studies.", progress = "You are certainly impatient, {name}.", completion = "We will find a shred of good within these dragons, {name}.  Whether it is in the wild eggs you found, the bodies of the whelplings you slew, or the eggs that we have encouraged Nyxondra to lay... we will find an untainted black dragon.", objectives = "Witness the final piece of Rhea's studies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27771] = { id = 27771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Third Sample: Implanted Eggs", description = "Nyxondra is being held against her will.  She is hidden from her brood, right in the middle of their breeding grounds.  She lays eggs, but they will be taken away before she can see them hatch.\n\nCruel?  Perhaps... but not nearly as cruel as the treatment that their dragonflight showed my mistress.\n\nShow me that I can trust you, {name}.  Take Nyxondra's eggs, and bring them here.  You will need to beat Nyxondra into submission before you can take them.", progress = "Remember, {name}... this is for the good of the black dragonflight.  We are here to redeem them, not to hurt them.  This is but a step in their recovery.", completion = "You have done everything that I have asked you, without question.  Our job here in Lethlor Ravine is done.\n\nIt is now time that I revealed everything to you.", objectives = "Obtain 3 of Nyxondra's Eggs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27772] = { id = 27772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Venerable Doctor Blam", description = "I made a calculated decision in revealing my identity to you, {name}.  I needed you to trust me, but I can no longer stay here in Lethlor Ravine, as my cover has quite clearly been blown.\n\nYou may be able to slip away unnoticed, however.  Here, take the results of our research, and bring them west.  At Agmond's End, you will find a gnome who knows what to do with these samples.\n\nHurry, {name}!  You mustn't loiter here any longer than necessary!", progress = "Dr. H. Blam, at your service.  How can I be of assistance to you today?", completion = "Ooh!  Science stuff!  Let's see what you've got here...\n\nWild eggs?  Blech.  Useless.  These are never any good.\n\nOoooh, what's this?  Some sort of... pre-engineered egg?  This looks promising, but I don't want to know what Rhea had to do to get it.\n\nHmm... yes, some very nice corpses.  Very nice indeed.\n\nAlright, I'll see what I can do.", objectives = "Bring the Black Dragon Samples to Dr. Hieronymus Blam at Agmond's End in the Badlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27773] = { id = 27773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Step Three: Prophet", description = "All that yet stands between me and the temple is Prophet Jammal'an himself. He is the leader of the Atal'ai trolls here, a foul manipulator.\n\nKnow that you do not face a mere crazed troll, {name}, but an instrument of forces beyond your darkest comprehension. Yet you do not fight alone; my strength and the will of the Green Dragonflight go with you.\n\nProceed to the Den of the Caller, left through the Hall of Ritual, and then down into the Hall of Bones. At the bottom, you will find Jammal'an.", completion = "He has escaped! I should have known it would not be so easy.\n\nThe path is clear, {name}. It is time to return.", objectives = "Defeat Jammal'an the Prophet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27774] = { id = 27774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Easily Swayed", description = "The most immediate threat to Fuselight is, without argument, the colony of ogres to the northwest.\n\nMost of our ogre neighbors used to be warrior-types, but it seems that more and more of them are practicing magic.  I won't have an army of ogre-magi at my doorstep.\n\nGo take out some of those Dustbelcher ogres.  Hopefully they'll get the picture and avoid messing with the might of Fuselight.", progress = "I'll feel much better when those ogres are gone.", completion = "I wonder where all of these ogre-magi are coming from?  Curious times, indeed.", objectives = "Slay 9 Dustbelcher ogres at Camp Kosh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27775] = { id = 27775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When the Going Gets Tough, Cheat", description = "I just can't get my invention to work!  Gah!\n\nThat's it, I've decided.  I'm going to cheat and use magic.\n\nWhat my invention really needs is a solid piston that's thin enough to fit through a narrow copper tube, but strong enough to withstand repeated impact without breaking.  The magical rods carried by those ogre magi to the north should work perfectly.\n\nFrom what I can tell, only the instructors carry the strong staves.", progress = "I don't like to stoop to using magic on my inventions, but this is somewhat of an emergency.", completion = "A perfect fit!  My goat puncher is finally finished!", objectives = "Obtain an Instructor's Rod from an Ogre-Mage Instructor at Camp Kosh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27776] = { id = 27776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Goat Time, Baby", description = "We have a little bit of a goat problem here in Fuselight, in case you haven't noticed.  They'll eat anything, and they seem to have taken a liking to the piles of cogs and gears that we tend to leave sitting around.\n\nIt's getting really annoying!\n\nYou'll find most of the billy goats wandering around the edge of town, near the cliff's edge.  Use this device on them to give 'em a little \"nudge\".", completion = "Well done!  I have no doubt that those goats will be back, but they'll think twice before they nibble my cogs again!", objectives = "Use Garyanne's Goat Puncher on 12 Billy Goats in Fuselight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27777] = { id = 27777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Core Access Codes", description = "The expedition's numbers are extremely large, user {name}.\n\nDealing with them by conventional means would take you an estimated 2,700,136.5 hours.\n\nWe can make use of a powerful source of energy held within expedition's crawler vehicle.\n\nWe will need the fusion core's access codes to accomplish this.\n\nMekgineer Twizzleflux has these codes and can be found at the Starwatch Tower to the southeast.\n\nI've uploaded jamming frequencies to a scrambler.  Use it to temporarily disable Twizzleflux's defenses.", progress = "Did you succeed, {name}?  I estimated your chances of survival at 68.5%.", completion = "Excellent job, user {name}.  We must obtain access to the fusion core now.", objectives = "Obtain the Core Access Codes from Twizzleflux the Insane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27778] = { id = 27778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hacking the Wibson", description = "It is true.  New expedition crews have arrived by sea.\n\nMy scanners detect that they already have been afflicted by the curse phenomenon.\n\nYou must hurry and go aboard the M.A.C. Diver.  The access codes will give us control over the fusion core's functions, but there is still a layer of security we must bypass.\n\nUser {name}, I must ask you to hack a very sophisticated mainframe known as the \"Wibson.\"\n\nDo not worry I will provide you with further instructions.", progress = "Greetings, user {name}.", completion = "I am in control, user {name}.  But I cannot keep the core temperature stable indefinitely.", objectives = "Hack the Wibson Mainframe on top of the M.A.C. Diver.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27779] = { id = 27779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnomebliteration", description = "I have downloaded my program to the fusion core and have complete control over it.\n\nI've created a small pocket of air inside to avoid vaporizing user {name}.\n\nI will yield control of all movement functions so I can dedicate my cycles to keeping the core stable.\n\nGo down the hill and neutralize as many of the expedition members as possible.\n\nMy analysis reveals you might feel... \"guilt\" as a result of such high fatality numbers.\n\nUser {name}, you must be assured that expedition members are without hope.", completion = "It is done, user {name}.  I thank you for your assistance with this unfortunate task.", objectives = "Obliterate 512 Crazed Gnomes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27780] = { id = 27780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Said the Words...", description = "Now that you're familiar with the ritual, it's time for you to perform it in the city. Dozens of our brethren have already infiltrated the city and made their way to the ritual sites.\n\nI want you to visit the portal ritual sites in Stormwind's Dwarven District, Park district, and Cathedral Square. The teams there will have made most of the preparations and all you need to is read the last part of the incantation from the book.\n\nVery soon, {name}, Stormwind will find itself awash in wind and water.", completion = "You've done an excellent job tracking down and combating the cultists, but I fear they are right about one thing. We will never know if we've gotten them all.", objectives = "Disrupt the cultist rituals in the Dwarven District, the Park, and the Cathedral District by reading the incorrect words from the Book of Incantations.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27781] = { id = 27781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Machination", description = "<Bzzzzzzzzzzzzt.>\n\n<Bzzzzzzzzzzzzt.>\n\nHe-hello? {name}, are you there? Are you still alive? Hello?\n\nOh good, you're still there! What in the name of Lordareon are they building? It's some sort of mechanized monstrosity! You have to stop them from completing that...that...thing! \n\nThrow out the rules, do whatever you have to do to thwart them!", completion = "<Bzzzzzzzzzzzzt.>\n\nYou're nearing the heart of their domain. There will likely be an extremely fortified door protecting the inner sanctum of the entire Defias operation. See if you can find anything that might pry it open!\n\nI suggest a stealthy method!", objectives = "Destroy the Foe Reaper 5000.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27782] = { id = 27782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mathias Needs You", description = "We've had some good times. I'm really sorry to see you go. But, Mathias says he needs you.\n\nHe said it's urgent!\n\nSo, you want to grab a drink or something after whatever, <buddy/lady>?", completion = "Good, you're back. We know where Cho'gall's ultimate weapon is located!", objectives = "Speak with Master Mathias Shaw at the Twilight Citadel in the Twilight Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27783] = { id = 27783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garona Needs You", description = "We've had some good times. I'm really sorry to see you go. But, Garona says she needs you.\n\nShe said it's urgent!\n\nSo, you want to grab a drink or something after whatever, <buddy/lady>?", completion = "Good, you're back. It's about time. We know where Cho'gall's ultimate weapon is located!", objectives = "Speak with Garona Halforcen at the Twilight Citadel in the Twilight Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27784] = { id = 27784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hammer of Twilight", description = "While you were in the mine, I was able to figure out where the Hammer of Twilight is being kept. They created it at the Altar of Twilight to the south.\n\nMore important than that, the cultists have made a critical error: Cho'gall is personally overseeing its final construction.\n\nMany SI:7 died to bring us this information.", completion = "The Hammer of Twilight floats in the middle of the altar, unprotected....", objectives = "Get to the Hammer of Twilight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27785] = { id = 27785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Admiral", description = "<Bzzzzzzzzzzzzt.>\n\nI can't believe it...they're almost done rebuilding it! We don't have much time, {name}.\n\nAdmiral Ripsnarl, Vanessa's right hand man, is bound to be on board. We'll never get to her if he's still alive to do anything about it. You're going to need to scale the unfinished Juggernaut, find Ripsnarl, and kill him so we can get to Vanessa's private quarters on the top deck.\n\nBe careful, the Admiral bears the worgen curse and would take much pleasure in digging his claws into you!", completion = "<Bzzzzzzzzzzzzt.>\n\nYour exploits have gained quite the following in the intelligence community, {name}. Many top members of SI:7 have been earnestly watching you infiltrate the Deadmines through their own Stormwind Communicators.\n\nMathias Shaw himself wants to speak with you! I'll transfer you over momentarily.", objectives = "Kill Admiral Ripsnarl.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27786] = { id = 27786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hammer of Twilight", description = "While you were in the mine, I was able to figure out where the Hammer of Twilight is being kept. They created it at the Altar of Twilight to the south.\n\nMore important than that, the cultists have made a critical error: Cho'gall is personally overseeing its final construction.\n\n<Garona begins sharpening her blades.>\n\nMany Kor'kron died to bring us this information.", completion = "The Hammer of Twilight floats in the middle of the altar, unprotected....", objectives = "Get to the Hammer of Twilight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27787] = { id = 27787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skullcrusher the Mountain", description = "It was a trap! Cho'gall lured you in with the Hammer of Twilight so that his gronn could finish you off.\n\nSurvive and slay Skullcrusher the Mountain!", completion = "You did it, lad! You beat that damned gronn and sent Cho'gall packing into the Twilight Bastion.\n\nDon't you worry. With your help and that of your friends, we'll get in there and we'll kill Cho'gall once and for all!", objectives = "Survive and then slay Skullcrusher the Mountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27788] = { id = 27788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skullcrusher the Mountain", description = "It was a trap! Cho'gall lured you in with the Hammer of Twilight so that his gronn could finish you off.\n\nSurvive and slay Skullcrusher the Mountain!", completion = "You did it, {name}! You beat that damned gronn and sent Cho'gall packing into the Twilight Bastion.\n\nDon't you worry. With your help and that of your friends, we'll get in there and we'll kill Cho'gall once and for all!", objectives = "Survive and then slay Skullcrusher the Mountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27789] = { id = 27789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troggish Troubles", description = "I'll need some time to analyze these samples, as well as a break from this trogg-shooting duty.  Go man one of my turrets and take out as many troggs as you can.  I'll be here studying.\n\nThe turrets have two abilities: a regular shot, as well as an electrical overload, for when too many enemies get close!  Heh, heh.  Good luck.\n\nOh, and look out for the big, slow troggs.  You probably don't want to let them anywhere near you.", progress = "Not quite done yet.  Need some more time.", completion = "The results are in.  I've identified traces of corruption in all three samples you brought me.  Rhea will be quite disappointed.", objectives = "Enter a Blam Turret, then survive four waves of trogg attacks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27790] = { id = 27790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Defias Kingpin", description = "Hello there, {name}. I've heard a great deal about you. Listen closely, you're only going to have one solid shot at this.\n\nThe new Defias Kingpin must be inside the hut orchestrating this entire operation. I want you to go inside and take her down, for the sake of the hundreds of innocent people the organization her father started has killed and terrorized.\n\nI'm shocked that she would let you get so close to her domain without fleeing and waiting until more favorable conditions, but it seems we're in luck.", completion = "You very well may have saved all of Stormwind with your efforts here today, {name}. Vanessa may still be out there, but she is an insignificant threat now that the Juggernaut will be placed under our careful watch. Thank you.", objectives = "Kill the Defias Kingpin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27791] = { id = 27791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dustwind Dig", description = "I've got an idea, but it's a bit of a long shot.  Thankfully, long shots happen to be a specialty of mine.\n\nNorth of here, the Explorers' League has uncovered a new set of titan ruins beneath the sands.  If there's anything older and wiser than dragons, it's titans.  Heck, I've heard rumors that the titans CREATED the dragons.\n\nTalk to Lead Prospector Durdin at the camp to the north.  He'll have more information than I do about these titans.\n\nWhat did I tell you?  It's a long shot.", completion = "Titans?  You wanna know about titans?\n\nYou came to the right place, lad.  We're on the brink of somethin' big.", objectives = "Speak with Lead Prospector Durdin at Dustwind Dig in the Badlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27792] = { id = 27792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All's Fair in Love, War, and Archaeology", description = "First things first, though.  I'm not just going to sit here and tell you everything we've discovered down in those ruins.  We've got problems to take care of!\n\nMost pressing is those upstart Reliquary hooligans, just on the other side of the tomb.  They're makin' off with all of our loot!  Don't they know that diggin's dwarf work?\n\nHunt down a few of their \"excavators\" - more like bandits, if you ask me - and bring some of these precious artifacts back to me.\n\nTHEN we'll talk titans.", progress = "Your bags look heavy.  Heavy with liberated artifacts, I presume?", completion = "Chalice... worthless.\n\nVase... counterfeit.\n\nHieroglyph... interesting, but rather common.\n\nWhat's this?  I've never seen trogg craftsmanship of this caliber!  You've stumbled upon something rare indeed, {name}.\n\nAlright, fine.  Let's talk titans, shall we?", objectives = "Obtain a Broken Chalice, a Dusty Vase, an Earthen Hieroglyph, and a Trogg Tool.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27793] = { id = 27793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Protectors", description = "You heard a good amount of rumbling happen in the tomb's central chamber.  Those two large statues did look awfully suspicious.", objectives = "Investigate The Warden and The Sentinel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27794] = { id = 27794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Blam", description = "Inside the chest, you find a small, circular device, resting upon a cushion.\n\nIf there are any titan artifacts to be found here in the tomb, this is it.  You resolve to bring it back to Dr. Blam.", progress = "Well?  Has our long shot paid off?", completion = "Just one tiny little device?\n\nI never did understand those titans.\n\nVery well!  Let's see what this peeper can do.", objectives = "Bring the Eye of the Watchers to Dr. Hieronymus Blam at Agmond's End in the Badlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27795] = { id = 27795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tides of Darkness", description = "The battle's proceeding just the way I wanted it. With their warriors nearly exhausted, I've sent in our cavalry.\n\nWhat I wasn't expecting was ogres. Our knights are well matched against the brutes, but they're going to need help.\n\nI need you back on the field right away, {name}. Few can bring down an ogre on foot, but I think I can count on you. Don't disappoint me.", completion = "Going toe to toe with ogres is impressive, {name}. I'm glad I've got soldiers like you out here.", objectives = "Slay 6 Stonard Ogres.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27796] = { id = 27796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warden's Pawn", description = "Once those Reliquary honks got here, we panicked, and we all just started looting indiscriminately.\n\nA lot of bad archaeology happened that day.\n\nLuckily, Olga happened upon this small jade statue.  We thought it to be a key of some sort, but can't figure out what it opens.  Maybe you'll have some better luck with it.", completion = "<The statue clicks into place on the large stone slab.>", objectives = "Find a use for the Warden's Pawn within the Tomb of the Watchers in the Badlands.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27797] = { id = 27797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sentinel's Pawn", description = "We very nearly had this statue stolen from us by one of Bloodwatcher's Reliquary stooges.  We managed to catch him in the act, and we've retrieved the statue, but it hasn't really paid off.\n\nIt appears to be a key of some sort, but I can't find the lock anywhere inside those ruins.  You feel like giving it a try?", completion = "<The statue slides into place on the cold marble slab.>", objectives = "Find a use for the Sentinel's Pawn within the Tomb of the Watchers in the Badlands.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27798] = { id = 27798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Water of Life", description = "Take my Water of Life and pass it into the corpse of the drowned dwarf.\n\nHe was a worker of metals in life, and though his body now feeds my loch, the Water will allow him to tell you what you want to know.\n\nThen take your information and be gone from my demesne.", completion = "The Hammer of Twilight? And you say you got this information out of a drowned Wildhammer dwarf?\n\nYou're kidding, right?", objectives = "Use the Water of Life to extract information from the Corpse of Forgemaster Finlay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27799] = { id = 27799, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Said the Words...", description = "Now that you're familiar with the ritual, it's time for you to perform it in the city. Dozens of our brethren have already made their way to the ritual sites.\n\nI want you to visit the portal ritual sites on the second level of the Drag, in the Valley of Honor near the Hall of the Brave, and near Orgrimmar's west gate. The teams there will have made most of the preparations and all you need to do is read the last part of the incantation from the book.\n\nVery soon the city will be consumed in flame.", completion = "You've brought many of these traitors to justice, {name}, and yet their numbers keep growing. I fear we won't be able to stomp out all these rituals in time...", objectives = "Disrupt the cultist rituals in the Drag, the Valley of Honor, and near the city's West Gate by reading the incorrect words from the Book of Incantations.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27800] = { id = 27800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back Under Cover", description = "The cultists seem assured of their victory, although we have captured many of them. We must find out more about the ritual mentioned by the cultist you questioned.\n\nThese rituals must be the core of their plans to attack Orgrimmar.\n\nTake one of the robes from the arrested cultists; it's not like they're going to need them anymore. Put it on and go back to the cultist outpost at the Jaggedswine Farm in Durotar and see what you can learn about these rituals and their place in the cult's plans.", progress = "It's good to see you again, {name}. We thought the Warchief might have gotten his hands on you.", completion = "You need to familiarize yourself with the portal ritual quickly. We've sent dozens of brothers into the city, but only so many can evade capture. We're relying on you, {name}.", objectives = "Put on your Recruit's Robe, go to the Jaggedswine Farm and get the Book of Incantations from Overseer Jintak. Read from the Book of Incantations near the Cultist Altar to practice the ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27801] = { id = 27801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Show Me Your Papers", description = "My men recently discovered a group of cultists attempting to sneak into the city. The flow of traffic into Orgrimmar has come to a halt. The Warchief has decreed that all visitors must be searched before they can enter the gates. Take this copy of his proclamation and read it to the people assembled at the front gates, then assist the guards there in searching those who wish to enter.", completion = "So there were more cultists waiting to be admitted to the city? It's a good thing that you caught them, {name}. Reading over the note that you found, it seems they're planning something big.", objectives = "Go to the front gates of Orgrimmar, read the Warchief's Proclamation and search 5 Orgrimmar Citizens. Keep anything suspicious that you find.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27802] = { id = 27802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arrest the Infiltrators", description = "The note you found can only mean one thing. The warchief's proclamation was too late; they already have infiltrators at work in the city.\n\nThis note contains instructions and locations for cultists to meet, but it doesn't say what they're doing. Our enemies have grown smarter. It's going to be tough to track down all of them, but we have to get as many as we can. Use these cuffs to arrest the infiltrators and then deliver them to Warden Gartok Ragefist at the Ring of Valor in the Valley of Honor.", completion = "So they're preparing some kind of ritual all over the city? Orgrimmar city is infested with cultists and their sympathizers and the warchief is at wit's end. We must do something!", objectives = "Use the Heavy Manacles to arrest 5 Cultist Infiltrators and bring them to Warden Gartok Ragefist at the Ring of Valor in Orgrimmar's Valley of Honor. After you've returned with your prisoners, question the Detained Cultist.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27803] = { id = 27803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome Relief", description = "I've got boys formin' defensive lines on all sides of the town, keepin' back the elementals streaming from the torn ground. They're good lads and they've been holdin' firm, but even the sturdiest dwarf tires eventually.\n\nThey're split into shifts: one hour of rest for every hour on the line. Best I can get'm with the men we have.\n\nIf you want to be helpin', pick a line and take up a shift. Give some of my boys a welcome breather. Report back in once you've killed several of the elementals.", progress = "Don't be dallyin'. These men are pourin' every fiber of their bein' into holding this town, and I'll not see them insulted by the presence of anyone that won't hold their weight.", completion = "Good work, boy. Good to have another capable set of hands about.", objectives = "Kill 8 Subjugated Firestarters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27804] = { id = 27804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Only Homes We Have", description = "We've already been pushed back farther than I'd hoped, but I'm not about to give up our homes to these mongrels. They may burn them, pillage them, and spit on the rubbled remains, but we'll still fight to take them back.\n\nThat being said, I rather like them not burnt. I have the boys running buckets from the well to try to keep the fire down. If you'd join them, they can help out by tossing you buckets so you don't have to make the runs.", progress = "As long as we work together, we can overcome anything the Twilight's Hammer might throw at us.", completion = "Thanks for your help. Every little bit makes a difference.\n\nWe'll keep the water going until we can push the Twilight back.", objectives = "Extinguish 50 fires at Firebeard's Patrol.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27805] = { id = 27805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Small Comforts", description = "You're the new face that's meant to be helping Keegan out I take it? Pleasure to meet you. Maybe you can lend a favor or two more to the troubled Wildhammer that have made refuge here.\n\nWe were all forced to retreat to this building quickly, and some of us left behind things of great value in our destroyed homes nearby. Would you mind bringing them back after you go out there? You would bring happiness to some very troubled souls.", progress = "Were you able to find their valuables. I know it seems so minor, but little things make a big difference to some people in times like these.", completion = "You are very generous. Thank you.\n\nThere's a lot of darkness in our world these days. We appreciate the light that you've brought here.", objectives = "Find and return Meara's Dried Roses, Parlan's Ivory Hammer, and Aprika's Doll.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27806] = { id = 27806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honorable Bearing", description = "Iain, my second in command, bore the body of one of our fallen heroes to the cathedral to the west. He's the man I've put in charge of reforming a wing of gryphon riders from whatever scattered forces he can find. I would like you to help him.\n\nI should impress upon you the urgency of this task. We will not be able to hold here forever; the Twilight's Hammer or the Dragonmaw orcs will eventually overwhelm us. Putting together an active gryphon wing may be our only hope for surviving these conflicts.", completion = "Greetings, {race}. Sent by Keegan?", objectives = "Speak to Iain Firebeard at the Firebeard Cemetery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27807] = { id = 27807, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clan Mullan", description = "If we're going to pull a full gryphon wing back together, we're going to need to move fast to gather the survivors before they leave or get picked off. I've got a bead on a few groups of riders that stuck together. I'm leavin' to find the Thundermar riders and the Moore riders shortly.\n\nThe Mullans were heading up west to the Crucible of Carnage last I saw. Go see if you can convince Duglas Mullan to join up with Keegan - he should owe him a favor or three.", completion = "Iain sent ya?\n\nYou don't look like a Firebeard to me. Why exactly should I be listenin' to anything you say?", objectives = "Speak to Duglas Mullan at the Crucible of Carnage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27808] = { id = 27808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stubborn as a Doyle", description = "The Doyle riders were last spotted convergin' in the trees to the south, on the border of the Obsidian Forest. They're a stubborn bunch and are likely to take some convincin' if they're going to join up with us.\n\nYour best bet with Keeland Doyle is to tell'm Cailin Longfellow's taken up shelter with us back at the town. Keeland's got a good soft spot for her and she just might be enough to convince him to drag all his boys along.", completion = "It seems the Doyles suffered the worst of the attacking Twilight drakes.\n\nIt's clear that they fought to the end: not a single rider's footprint more than a few yards from his gryphon. It's doubtful there were any survivors.", objectives = "Speak to Keeland Doyle in the Highland Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27809] = { id = 27809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Firebeard Bellows", description = "I also need ya to seek out Mackay and his men on the other side of the Devouring Breach, at the Gorshak War Camp.\n\nThe Dragonmaw didn't survive the initial onslaught, and Mackay's lookin' to ransack what he can of their camp to supply our fight. There shouldn't be much convincin' necessary, but they'll likely want a hand wrappin' things up there before they make their way back to Keegan.\n\nGive'm a boot in the arse from ol' Iain if ya have to.", completion = "Bout that time, eh? Help us wrap things up then.", objectives = "Speak to Mackay Firebeard at the Gorshak War Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27810] = { id = 27810, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fighting Spirit", description = "Keegan wants the Mullans to take wing with'm eh? If there's a dwarf I'd fly for, he'd be it. Still, I don't get why he'd be sendin' an outsider to be recruitin' me - not right polite by my standards.\n\nI'm guessin' ya don't last 20 seconds with any of my boys, at the bar or in the battlefield. Prove me wrong. Take one of'm down in a fight and then I'll think about flyin' with ol' Keegan.", progress = "Naw, I'll not be fightin' ya. Get in there and challenge one of my boys if you've got a gut on ya at all.", completion = "That's the stuff! Not half bad. You've got a bit of fight in ya after all.", objectives = "Challenge and defeat one of the Mullan Gryphon Riders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27811] = { id = 27811, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scent of Battle", description = "Don't let Duglas fool you, the Mullans have been itchin' to take wing again, and if there's anyone we'd do it for, it's Firebeard.\n\nWe left our gryphons in the Highland Forest to the south to hunt and to get away from the sounds of battle for a bit. They deserved a rest.\n\nIf you want us back in the air soon, you'd do well to help us bring our gryphons back in.\n\nTake this piece of charred highland birch. We use it during training - as soon as they smell it, they'll come straight back to us.", progress = "We're not going to be much use to you without our birds.", completion = "Good on you. I always feel like a part of me is missing when my gryphon isn't nearby. I can't speak for Duglas or the rest of the clan, but I'll be ready to ride at Firebeard's call.", objectives = "Find 8 Mullan Gryphons and dispatch them back to their gryphon riders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27812] = { id = 27812, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Loyalty of Clan Mullan", description = "Your point's made. Keegan can count on us. We'll meet'm back at town as soon as all the boys are rallied up.\n\nYou're tough for not bein' a Wildhammer. Guess they breed'm good where you come from too.\n\nStill, haven't seen ya drink yet. That'll be the real test.", completion = "Ya got the Mullans. Good news! They're worth more than their weight in a fight, and they ain't exactly skinny.", objectives = "Return the news on Clan Mullan to Iain Firebeard at the Firebeard Cemetery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27813] = { id = 27813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death Worthy of a Dragonmaw", description = "The Twilight sacked this town, killin' most of the Dragonmaw that lived in it. A few survived though, and they're not right keen on us takin' liberties with their supplies.\n\nNot that that matters much.\n\nWell, I'm not right keen on them attackin' my boys. Kill'm off, chase'm out - I don't care, just get'm gone.", completion = "That's more like it. Let's finish gatherin' up supplies and get back to Keegan.", objectives = "Defeat 6 Dragonmaw Stragglers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27814] = { id = 27814, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anything We Can Get", description = "Stay back and forge more weapons?  Pah!  A Forgehammer has ne'er been afraid of battle!  Who needs the safety of home to make weapons?  Besides - there is oodles of raw material out here.  Those Dragonmaw weapons are worthless, but they can be smelted down to make actual weapons.  Bring me 8 Dragonmaw weapons so me daughter and I can forge real weapons out of them.", progress = "How many have you got so far?", completion = "Yer a good lad.  Have me thanks and a little gold for yer troubles.", objectives = "Bring 8 Dragonmaw weapons to Brom Forgehammer at Gorshak War Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27815] = { id = 27815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Somethin' for the Boys", description = "Cleaned up the camp and ran errands for Forgehammer?  Not bad for a wee {class}.  Take these to Iain at Firebeard Cemetery, and he should reward you for a job well done.", progress = "What have we here?", completion = "Hah! Looks like their raid went mighty well then. I'll have to buy ol' Forgehammer a round once we finish with this mess.", objectives = "Bring Forgehammer's weapons to Iain Firebeard at the Firebeard Cemetery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27816] = { id = 27816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Personal Request", description = "Shame about the Doyles. It's a fair miracle that as many of us made it out as is though, so can't count it as much of a surprise.\n\nThose louts at Thundermar are cowards. Even after tellin' them it was Keegan askin', they won't set foot outside of their town. I did rope in the Moores though, so that's at least three clans' worth.\n\nKeegan wanted to hear from ya personally when you returned. Go find'm in town.", completion = "It seems you had some luck bringin' riders back. Well timed too - we just pushed the elementals back, so we should have the arm room to lead an attack right away.\n\nThank you, {name}. You're a good {race}.", objectives = "Speak to Keegan Firebeard at Firebeard's Patrol.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27817] = { id = 27817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dropping the Hammer", description = "Thanks to you and Iain, we've got enough riders together that we can take the fight back to the Twilight.\n\nWe're trained to fight while ridin', but a second rider to handle the Stormhammer tends to be more efficient. I thought you might enjoy the honor.\n\nPick your gryphon and join the fight. Best be quick about it though - we're aimin' to clear every last one of those Twilight off of those floatin' rocks before the hour's out.", progress = "Today is the day that the tables turn.", completion = "Now that's how it's done, lad!\n\nWith a real gryphon wing back together, we can take the fight to the rest of the Twilight. You're welcome to fly with us anytime.", objectives = "Kill 12 Twilight Stormbenders and Servias Windterror using one of the gryphons at Firebeard's Patrol.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27818] = { id = 27818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slithering Signs", description = "I settled here well before Bogpaddle was founded, to brew my potions and find some peace and quiet. I know this swamp like the back of my old, gnarly hand.\n\nThere's been a change in the wildlife recently. Those winged snakes you may have seen in the stagalbog are wind serpents, and they haven't been seen around here for ages.\n\nThey're also prime for ingredients if they're the kind I'm thinking of. Be a dear and gather me some of their hearts, will you?", progress = "Don't be squeamish now.", completion = "Let's have a look then...\n\nMmm, oh dear. That's what I thought these were. They might still be usable, but it's horrid to have such things in my backyard.", objectives = "Collect 5 Intact Stagalbog Serpent Hearts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27819] = { id = 27819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "TEST - RVM" }
quests[27821] = { id = 27821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orcs and Humans", description = "With war raging across the entire world, the last thing we need is a Horde settlement right in our backyard. Redridge, Duskwood, even Elwynn itself are all a day's march from here.\n\nWe've made the first strike, and I don't plan to give the Horde a chance to catch their breath. So consider yourself deployed. Grab a weapon, join the rest of the troops out in the Bloodmire, and start killing orcs.\n\nReport back here after you've done some damage. I want you back alive...and that's an order. Dismissed!", completion = "More black on you than red... that's what I like to see. Looks like you've got what it takes, {name}.", objectives = "Slay 8 Stonard Warriors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27822] = { id = 27822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lumbering Oafs", description = "I want victory to be totally assured here. Having more resources isn't enough; we need to make sure the enemy has nothing.\n\nStonard's forces depend on the lumber gathered from the surrounding woods. The orcish peons that chop the lumber may not be warriors, but they still know nothing but hate for humans.\n\nShow no mercy. I want those peons killed and the supply of lumber to Stonard cut off completely.", completion = "We've had strikes on our own lumber line while you've been gone. This should at least put us on equal footing for gathering rates.\n\nGood work, {name}.", objectives = "Slay 5 Stonard Peons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27823] = { id = 27823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dwarf's Got Needs", description = "I can appreciate a good diggin' as much as any other dwarf, don't get me wrong.  It's just that... well, we do so much diggin', and so little drinkin', that sometimes I wonder if I should just hang up me shovel and head back to Ironforge.\n\nBut not today.  I've got some diggin' in me yet.\n\nThose Dark Iron dwarves at Hammertoe's Digsite - just north of here - make some powerful fine beer, right here in the desert.  You think you could pick up a few for me?", progress = "<Sigrun licks his lips in anticipation.>", completion = "<Sigrun instantly downs a dusty mug of shadowstout.>\n\nWow, this stuff is strong!  I knew they had beer, but I never expected them to have shadowstout!  That's my favorite shadowbeer!", objectives = "Obtain 15 mugs of Shadowstout.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27824] = { id = 27824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Good Stuff", description = "I've got a little proposition for you, if you're interested.\n\nThose Dark Irons were here before Durdin and his crew arrived.  That means that, once these titan ruins opened up, the dark irons were the first ones in there, lootin' all the good stuff.  I'll bet they've still got those treasures locked up inside Angor Fortress, northwest of here.\n\nYou've more than proven your ability to wallop a dwarf.  Head on into that fortress and wallop your way to titan treasure.\n\nI'd go with, but I'm drunk.", progress = "Back so soon?", completion = "Now here's some treasure!  I was beginning to worry that these weren't titan ruins at all!\n\nI'll show these to Durdin.  Thanks again, {name}.", objectives = "Search for treasure in the bottom floor of Angor Fortress.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27825] = { id = 27825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Survival of the Fattest", description = "We're hard-up for supplies, stranger.  With the black dragons raining destruction on what would be our hunting grounds, we have no way to get food.\n\nThe ogres to our southwest, however, have exactly what we need.  Within their grotto you should find plenty of meat and crafting supplies.\n\nThey may put up a fight.  Be on your guard.", progress = "Welcome back.", completion = "I imagine those ogres weren't too much trouble for you.  Here - some coin for your troubles.", objectives = "Obtain 6 pieces of Dustbelcher Meat and 10 sheets of Dustbelcher Silk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27826] = { id = 27826, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Dragon's Mouth", description = "<Dr. Blam stares at the egg in awed silence, blinks a few times, then looks up at you.>\n\nD... did you see that?  Incredible!  My titan thing idea worked!  With your help, of course.\n\nWe'll want to get this back to Rhea.  She's not at Lethlor Ravine anymore; it sounds like she blew her cover pretty well when she transformed into her true form in front of all those whelps.  She's now in the west, staying at an Alliance camp called Dragon's Mouth.\n\nShe'll be waiting for you.  And for that egg.", progress = "That's some precious cargo you carry there, {name}.", completion = "I'll take that egg out of your hands now.  We need to get this egg incubated... and hidden, quickly.  There are lots of angry dragons looking for this.\n\nIt's good to see you again, by the way.", objectives = "Bring the Purified Black Dragon Egg to Rhea at Dragon's Mouth in the Badlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27827] = { id = 27827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Swift, the Fierce, and the Stout", description = "In my haste to escape from Lethlor Ravine, I forgot to tie up one loose end: Nyxondra.  She's free, and she's sounded the alarm among the black dragonflight.  Half the flight is here in the western Badlands, combing for this egg.\n\nI'll take care of hiding the egg.  You're going to take care of some of the more troublesome dragons.  And you'll have help.\n\nTalk to Eric, over on the other side of camp.  He and his brothers will be joining you.", completion = "You're the {race} we've been waiting for?  It's about time you got here.  My legs could use a stretch.\n\nCome on boys!  Let's go kill us some black dragons!", objectives = "Speak with Eric \"The Swift\" at Dragon's Mouth in the Badlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27828] = { id = 27828, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eric, the Utility Dwarf", description = "Before we get too crazy what with the dragon-killin', let me tell you a little bit about how I fight.\n\n\"The Swift\" is what they call me, and here's why: I'll dash straight into your enemies - helmet first, mind you - and stun 'em for a few seconds.  I also keep a few potions with me for tight spots.\n\nWhy don't we practice fightin' together?  Head out into the field, and try out my abilities.", progress = "We're not through yet, {name}.", completion = "I'm not what you'd call \"very strong\" or \"battle-hardened\", but I get the job done my own way.\n\nLookin' forward to fightin' with you.  I never fought with a fancy-lookin' {class} before.", objectives = "Use Eric's Charge and Eric's Pocket Potion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27829] = { id = 27829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wrath of a Dragonflight", description = "Hello, {name}.  It looks like you four have had time to become well-acquainted.\n\nI have my first assignment for you.  Kalaran, an ancient black dragon of considerable power, has joined in the hunt for the egg we are protecting.  We need to stop him before he gets too close.\n\nYou will find him and his minions at the Dustbowl, northeast of Dragon's Mouth.  Hunt him down and defeat him.  You will likely need the help of your new dwarven allies.", completion = "One less dragon to worry about, one step closer to redemption.  Onward, my soldiers!", objectives = "Slay Kalaran the Annihilator and 4 Darkflight Soldiers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27830] = { id = 27830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Their Hunt Continues", description = "The black dragonflight means business.  It appears that they've taken over a large portion of New Kargath, the large Horde settlement northwest of Dragon's Mouth.  Their troops are under the command of General Jirakka and his champion, Moldarr.  They must be stopped.\n\nWe dragons do not take part in the squabbles between Horde and Alliance, but I do understand the risk you take in entering New Kargath.  Please, heroes... be careful.", completion = "Two more dangerous black dragons have been removed from this egg hunt.  Your greatest task, however, still awaits.", objectives = "Defeat General Jirakka, Moldarr, and 6 Blackflight dragonspawn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27831] = { id = 27831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sorrow and the Fury", description = "My greatest regret is the treatment that we - no, I - gave to Nyxondra.  I forced her to lay eggs, then I performed experiments on them.  Over, and over, and over again.\n\nEven as a mother myself, I can only imagine her sorrow.\n\nNo... I mustn't be weak.  Our work is, after all, for the benefit of future generations of black dragons.  Her sacrifice was necessary.\n\nShe circles the Ruins of Kargath, northwest of New Kargath, insane with fury.  Please, heroes... put her out of her misery.", completion = "Just think... Nyxondra may end up being the mother of the new black dragonflight.  In death, she has given a gift to the future generations of Azeroth.", objectives = "Slay Nyxondra and 12 of Nyxondra's Broodlings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27832] = { id = 27832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hidden Clutch", description = "With the major black dragons out of the Badlands, it is now safe to move the egg again.  You will find me on a small plateau, north of New Kargath.\n\nCome and find me.", completion = "The egg must always be moving.  We are not safe anywhere.\n\nDeathwing, even in his madness, knows all the hidden places in this world.  The egg must not rest.", objectives = "Speak with Rhea at The Hidden Clutch in the Badlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27833] = { id = 27833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Half-Ton Holdouts", description = "I'd say we have a dragon problem, but it seems like they're a little more interested in New Kargath than they are in our small encampment.  Nevertheless, I've got top men focused on keeping the dragons at bay.\n\nOne problem that has gone unchecked, however, is the ogre camp to our southwest.  A small army of combatants seems to have appeared outside of their hovel.\n\nWe can't sit and wait for them to flank us, soldier.  Thin their ranks before they thin ours.", completion = "Thank you, {race}.  However, I'm afraid I don't have much to give you, other than this passionate round of applause.\n\n\n\nOh, I do have these.  Here, take your pick.", objectives = "Slay 12 Dustbelcher Combatants. You may kill Dustbelcher Maulers or Dustbelcher Shaman.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27834] = { id = 27834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baelog, the Glass Cannon", description = "Before I start droppin' arrows on those dragons, I'd better introduce myself.\n\nI'm Baelog, the muscle of this group.  My sword bites like a crocolisk, and my arrows sing like banshees.  I tend to wear down quickly, however, and can't take as much punishment as either of my two brothers.\n\nYou give the word, and I'll send an aimed shot right through your target's heart.  I can also cheer my brothers on, sending 'em into a battle-fueled frenzy.\n\nWhy don't we go try fighting together?", progress = "We're not quite ready yet.  A little more practice, then we'll get with the dragon-slaying.", completion = "I think you're ready, {name}.  You're getting the hang of this.", objectives = "Use Baelog's Valhalla Shot and Baelog's Warcry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27835] = { id = 27835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Olaf, the Big Fella'", description = "You may not have noticed, but I'm pretty big, as far as dwarves go.\n\nI make sure that my two brothers here don't get into too much trouble.  They're small, and they don't have a big shield like me.  I'm big, and I can handle a few monsters hitting me!  Plus, if I'm careful, I can usually get them to hit my shield instead!\n\nI can protect you, too.  Come on, let's go practice for a bit.  I'll make sure the enemies attack me, and not you.", progress = "Don't worry, little {race}.  I'll protect you.", completion = "See?  No need to worry when Olaf is around.  Just let me know, and I'll protect you from the monsters.", objectives = "Use Olaf's Shield Wall and Olaf's Mighty Shout.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27836] = { id = 27836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stopping the Spread", description = "Slaying the foul creatures that plague the river will not be enough, {name}.\n\nA new generation of these monstrosities already threatens to spawn within our holy waters.\n\nSeek their foul eggs and destroy them.", completion = "I thank you, {name}.  This will make our prophetic visions that much clearer.", objectives = "Destroy 6 Slitherer Eggs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27837] = { id = 27837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trespassers in the Water", description = "Shortly after Uldum's protective barriers fell, the Vir'naal river became afflicted with a terrible corruption.\n\nWhether it was brought here maliciously or accidentally is not of great significance.\n\nThe result is the same.  As the river becomes clouded so does our ability to peer into what the future holds for us.\n\nLook outside, {class}.  These foul creatures were never meant to live in the pristine waters of our river.\n\nSlay them so that the river may grant us visions once again.", completion = "Yes, {name}.  I can feel the disruption in the river fading.\n\nYet, I feel the source of this taint still lingers.", objectives = "Slay 8 Stillwater Slitherers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27838] = { id = 27838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Root of the Corruption", description = "You might have dealt with the symptoms of our problem, {name}.  But I've been studying these foul beasts and the eggs are not laid here by them.\n\nThe stream from the current carries their eggs to the dam, but whatever is laying them will be found upstream.\n\nGo northeast, to the river's main source, and deal with the root of the corruption.", progress = "Is it done yet, {name}.", completion = "Yes.  The waters are clearing up.\n\nI am certain I will be visited by a vision before the High Council meets.\n\nBe warned, {race}.  My vote will only be swayed by what I see.\n\nYou might have helped us greatly here today, but if the vision sways me to make a case against war then that is the way my vote will be cast.", objectives = "Go to the northeastern source of the Vir'naal River and slay Scalemother Hevna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27839] = { id = 27839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Weapons", description = "Though we aren't formally at war yet, the Neferset do not hesitate to imprison or kill all who trespass upon their territories.\n\nKing Phaoris refuses to reciprocate, even when they use our lands to smuggle stolen relics from the tombs of our ancestors.\n\nMy scouts report that the Neferset are about to move a major shipment of looted weapons south of here.\n\nI've instructed the laborers you recruited to assist you.  Call upon them with this horn when you find the smugglers and recover the weapons.", progress = "You've returned, {name}.  How did the operation go?", completion = "This is quite timely.  I will distribute these armaments to my best men and to the laborers that you recruited.\n\nI've a feeling they'll show as much courage as my best trained captains.", objectives = "Retrieve the Ancient Tol'vir Armaments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27840] = { id = 27840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draenethyst Crystals", description = "The lost ones who live in the Fallow Sanctuary look as we look, but they are monsters... driven mad by the rigors of our journey to Azeroth.  Once our brethren, they now live in the Fallow Sanctuary to the west, catching or killing any who wander near.\n\nAnd they have stolen something sacred to us--draenethyst crystals.\n\nWe lack the force to enter the Fallow Sanctuary and reclaim our stolen draenethyst from among their huts and campfires, but without those crystals... we too may lose our way.", progress = "Do you have the crystals?", completion = "Thank you, {name}.  We, are in your debt.", objectives = "Collect 5 Draenethyst Crystals from the Fallow Sanctuary.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27841] = { id = 27841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grateful Dead", description = "It's good to visit with friends and family again, though I may have overdone it... I've already eaten everything they made for me!\n\nMight I trouble you for some more of that delicious Bread of the Dead? I'd be most grateful...\n\nChapman there sells the recipe, I think.", progress = "You don't have any Bread of the Dead, do you?", completion = "Ah, more delicious Bread of the Dead, thank you!\n\nPlease, take this in return... a little something fun for the holiday.", objectives = "Acquire some Bread of the Dead and give it to the Cheerful Goblin Spirit in Orgrimmar's graveyard.\n\nUse an Orange Marigold to see the otherwise invisible spirit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27842] = { id = 27842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Only the Beginning", description = "I miss the days when legions of powerful ogres marched by the Horde's side into battle, the pathetic Alliance cowering at their ferocity. Perhaps those days will return before I am gone to the ancestors.\n\nHowever, that is not the case now. An ogre magi, Glubtok, has joined forces with the despicable Defias Brotherhood and acts as Foreman over their mining operations. The pathetic fool! End his life for me, and for the spirit and glory of the Horde!", completion = "Do not be alarmed, {name}. I am close to you, waiting in the shadows. You've done well.\n\nYou must continue the mission here - I am too valuable to risk my life against petty criminals like these.", objectives = "Kill Glubtok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27843] = { id = 27843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinforcements Denied", description = "Just killing ogres won't be enough. The ogres themselves are being summoned onto the battlefield far too rapidly.\n\nI need you to go far behind the enemy line and seek out their summoners. The orcs are using warlocks to bring their reinforcements in.\n\nCut down the warlocks, and the portals should close. There aren't many of them; a quick, surgical strike should cripple the enemy.", completion = "Once again, well done. With a few more pushes the battle will be ours.", objectives = "Slay 3 Stonard Warlocks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27844] = { id = 27844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traitors!!!", description = "The goblins you'll find working with the Defias are officially traitors to the Bilgewater Cartel, the Shattered Hand, and the Horde itself!\n\nI haven't yet been initiated into the Shattered Hand, so my loyalties lie strongly with my people. Helix Gearbreaker apparently has no time for such associations, and works on building a mast for the Defias Juggernaut. On behalf of Miss Mayhem and myself, would you kindly 'dispose' of Helix?", progress = "Yes?", completion = "My employers do not take kindly to traitors.\n\nOn the flip side, they are renown for their kindness towards the loyal! You deserve to be rewarded!", objectives = "Defeat Helix Gearbreaker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27845] = { id = 27845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marking the Fallen", description = "We've taken more than we've lost, but we've still lost too much. Too many brave have given their lives for the Alliance out there. I want to make sure they're given proper honors no matter how fierce this battle gets.\n\nTake these flags out with you and place one on any fallen soldier you see. The protective wards on them won't offer much protection against any defilement, but it's better than nothing. I'll be able to better judge how many we've lost from a distance, as well.", completion = "Thank you, {name}. Those soldiers deserve better than to be left face down in the mud.", objectives = "Use the Banner of the Fallen to mark 7 Fallen Marshtide Footmen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27846] = { id = 27846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grateful Dead", description = "It's good to visit with friends and family again, though I may have overdone it... I've already eaten everything they made for me!\n\nMight I trouble you for some more of that delicious Bread of the Dead? I'd be most grateful...\n\nChapman there sells the recipe, I think.", progress = "You don't have any Bread of the Dead, do you?", completion = "Ah, more delicious Bread of the Dead, thank you!\n\nPlease, take this in return... a little something fun for the holiday.", objectives = "Acquire some Bread of the Dead and give it to the Cheerful Worgen Spirit in Darnassus' graveyard.\n\nUse an Orange Marigold to see the otherwise invisible spirit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27847] = { id = 27847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Quite There", description = "These prototypes are going to change the face of Horde warfare when I perfect them! The issue I've been having is that their power sources don't allow for complicated combat maneuvers or large frames, both highly desired traits when it comes to fighting Alliance.\n\nThe Defias, with some help from goblin traitors like Helix, have almost completed the Foe Reaper 5000, a massive golem that will actually work!\n\nWe can't have that going public, can we? I'll lose customers!", completion = "Brilliant! Now all I have to do is finish my work, and my Mayhem Reapers will cause...mayhem...on any Horde front!\n\nAnd there won't be any Defias knockoffs to steal my profits!", objectives = "Destroy the Foe Reaper 5000.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27848] = { id = 27848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Good Intentions...Poor Execution", description = "The Defias plan to finish their Juggernaut and use it to lay waste to Stormwind. It is a noble cause any true orc warrior would embrace without a single thought!\n\nVanessa's fault lies in her execution of their plan. The ship is poorly constructed, the crew practically untrained, and, worst of all, there's a worgen in their midst!\n\nHis name is Admiral Ripsnarl, and he must be mercilessly slain in the name of the Warchief. Lok'tar ogar!", completion = "It's a shame that he was both a human and a worgen. Had he been a proud orc warrior I'd have liked to charge into battle alongside such a fierce combatant.\n\nWe can speak of ill-fated desires another day. It is time to take what is ours from the enemy.", objectives = "Kill Admiral Ripsnarl.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27849] = { id = 27849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Stonard", description = "This is it, {name}. We've made our final push into Stonard itself.\n\nI shouldn't have to remind anyone, but I'll say it anyway: We're not orcs, and we're not going to become them out of revenge or spite. Stonard will not be burned to the ground for us to dance on the ashes.\n\nNo, I want this done right. I want this surgical. Hold your head high and strike down any orc that picks up a weapon.", completion = "You've followed orders well, {name}. On behalf of the crown, I'm rewarding you for your bravery on the battlefield.", objectives = "Slay 6 Stonard Defenders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27850] = { id = 27850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Defias Kingpin", description = "The Shattered Hand has laid mostly quiet for years now.\n\nNo more!\n\nYou will be the instrument of our rebirth, {name}. Slay the Defias Kingpin and commandeer her ship for the Horde! We will outfit it as a proper orc warship and use it to finally lay waste to Stormwind\n\nAny survivors will spread word of our unstoppable power across all of Azeroth, and all will tremble before our might!\n\nGo now, VanCleef's death will be your greatest triumph yet hero.", completion = "COWARD!!! Vanessa VanCleef is a dirty human coward! How dare she flee from battle against the Horde and leave her unworthy subordinate to fight!\n\n<Kagtha composes herself.>\n\nNo matter. Her ship is reward enough. The citizens of Stormwind will bear first hand witness to our awe inspiring power using a ship made in part by the very architect of their city!", objectives = "Kill the Defias Kingpin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27851] = { id = 27851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cutting Supply", description = "We may not be flattening Stonard into dust, but I don't want to have to go in there a second time.\n\nI want you to gather any supplies you see in the town while you're there. Without food, they won't have any fighters after more than a day.\n\nThere should be crates scattered all over town.", progress = "What's the situation?", completion = "Good work, {name}. With this, it's only a matter of time until the orcs are fleeing for the portal or begging for surrender.", objectives = "Seize 5 crates of Stonard Supplies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27852] = { id = 27852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orcs and Humans", description = "War rages in the swamp, {name}. Vicious humans have settled north of the city and brought an army to our doorstep.\n\nThere is nothing in this swamp for them. Their sole reason for coming here is to attack us, unprovoked. We will not give them the pleasure of victory!\n\nWe are undermanned and I need every able orc to take to the battlefield. Go, and slay as many humans as you can.", progress = "I'm pretty sure you still have some slaying to do.", completion = "We will fight to the last orc, {name}. I hope you'll keep yourself alive long enough to properly destroy these trespassers.", objectives = "Slay 10 Marshtide Footmen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27853] = { id = 27853, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lumbering Oafs", description = "We are outnumbered by the Alliance. In their fear they send an army to crush a single settlement. But we will not give!\n\nWithout resources, their soldiers will be at a disadvantage. Human peasants busy themselves in the woods outside Marshtide Watch, gathering lumber to rebuild their crumbling walls.\n\nDeny them the wood, and their lives.", completion = "No true member of the Horde should find pleasure in killing such terrified weaklings... without challenge, victory has no true thrill.\n\nBut your dirty work has helped stave off the Alliance and protect our homes here. Be proud of your work for the Horde.", objectives = "Slay 5 Marshtide Peasants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27854] = { id = 27854, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tides of Darkness", description = "We have suffered many losses, {name}. Dreadmaul Hold has sent ogres from the Blasted Lands as reinforcements, but they can only send so many; the Alliance attacks them as well, even as we speak.\n\nThe Alliance has countered our ogres with mounted knights, a strategy that served them well in the Second War. We will need our strongest warriors to turn the tide of battle!\n\nReturn to the Bloodmire, {name}, and bring down those knights!", completion = "You are a true champion, {name}, to take the lives of so many on the battlefield. I hope it will be enough to save Stonard.", objectives = "Slay 6 Marshtide Knights.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27855] = { id = 27855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinforcements Denied", description = "The Alliance has brought in their mages to summon more reinforcements directly to the battlefield from beyond their fortress. This must be stopped!\n\nTheir numbers are few, but a single portal can turn the tide of battle. Attack their mages and shut off those portals!", completion = "With no link to the outside, the Alliance must rely on what they've brought to the swamp. We shall see if they can handle our home environment.", objectives = "Slay 3 Marshtide Mages.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27856] = { id = 27856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marking the Fallen", description = "Many warriors have met death to bring us victory, {name}. The fate of a true orc.\n\nI have seen the way the Alliance loots the bodies of our fallen, clutching at our goods like packrats. They will not defile our fallen heroes on this field.\n\nTake these wards with you to the Bloodmire. Place them on the bodies of our fallen warriors. I will be watching, to see how many have fallen, and to honor their sacrifice. Let us hope the spirits give us aid for our respect.", completion = "You honor both the dead and the living with your courage, {name}.", objectives = "Use the Banner of the Fallen to mark 7 Fallen Stonard Warriors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27857] = { id = 27857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We're Under Attack!", description = "The Alliance are at our walls!\n\nYour actions delayed them and weakened their forces, {name}, but in the end we are outnumbered. This is our last stand. Victory or death...\n\nFight with honor, {name}. They are within the walls as we speak. Drive the human dogs from Stonard, for the Horde!", progress = "There is no time! Go! Fight!", completion = "The Alliance is driven out! Stonard will be safe, thanks to your ferocity. Lok'tar Ogar!", objectives = "Slay 12 Marshtide Invaders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27858] = { id = 27858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rheastrasza's Gift", description = "Wait here.  I will retrieve the egg.", objectives = "Wait as Rhea retrieves the egg from the Hidden Clutch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27859] = { id = 27859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Egg Lives On", completion = "You were not the only mortal that Rheastrasza confided in.  I too earned the dragon's trust.\n\nI have already moved the real purified egg on to a safer location, away from the Badlands.  It will continue to grow, out of Deathwing's sight.\n\nThe red dragonflight is as benevolent as it is powerful.  It was Rheastrasza's final wish that I give this to you.", objectives = "Wait as Rhea retrieves the egg from the Hidden Clutch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27860] = { id = 27860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Ones", description = "When the Dark Portal closed many years ago, regret and fear seized many of us who had come to these lands. In their despair, they cursed the name of the Light, and sank into violence and hatred.\n\nThese fallen souls are now the Lost Ones, little more than mindless monsters, attacking all who approach. They grow more corrupt by the day, and as they die off, they have begun to kidnap from the Harborage..\n\nThey are beyond help, {name}. Their suffering must end. Will you put them from their misery?", completion = "It still pains my heart to have asked you to do this, though I know there is no other way. You have saved those of us still holding on from a terrible menace.", objectives = "Slay 12 Lost Ones in the Fallow Sanctuary.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27861] = { id = 27861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crucible of Carnage: The Bloodeye Bruiser!", description = "I was wondering when you'd show up, {name}! Having a past champion of the Ring of Blood here will be a huge draw! We're gonna be rich, buddy! RICH!\n\nAnyway, this is some old Dragonmaw fighting pit. Didn't take much modification to tune it up to our uses. I put out a few feelers, and got some heavy hitters from all around Azeroth to join in the carnage. Bout time to make some gold!\n\nYou know the drill, {name}. When you're ready, let me know and we'll get this show on the road!", objectives = "Get in the arena at the Crucible of Carnage and defeat Hurp'derp!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27862] = { id = 27862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crucible of Carnage: The Bloodeye Bruiser!", description = "Well well, if it isn't the once champion of anguish, {name}! I'm seeing good money in the future now that you're here! We're gonna be rollin in the dough, buddy! Filthy RICH!\n\nAnyway, this is some old Dragonmaw fighting pit. Didn't take much modification to tune it up to our uses. I put out a few feelers, and got some heavy hitters from all around Azeroth to join in the carnage. Bout time to make some gold!\n\nYou know the drill, {name}. When you're ready, let me know and we'll get this show on the road!", objectives = "Get in the arena at the Crucible of Carnage and defeat Hurp'derp!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27863] = { id = 27863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crucible of Carnage: The Bloodeye Bruiser!", description = "I'll tell you what, buddy, this place is a far cry from the rolling plains of Nagrand or the bloodbowl in Zul'Drak, but hey, I go where the gold's at! So welcome to Twi-Hi, pal.\n\nYou're new to this pit, so let me set you straight. I'm the fight promoter and this feisty troll next to me is Wodin, my bodyguard. You're the entertainment. When you wanna fight, let me know and I'll set up the match.\n\nIf you're ready and got a group of friends with you, we can start! What do you say?", completion = "Not bad, friend. You might make some gold out here - if you manage to stay alive.", objectives = "Get in the arena at the Crucible of Carnage and defeat Hurp'derp!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27864] = { id = 27864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crucible of Carnage: The Deadly Dragonmaw!", description = "You're going to love this one! The Dragonmaw heard you were entering the arena and they're determined to make sure you don't leave it.\n\nTime for some good ol' {race} on orc action! Let me know when you're ready to do this!", completion = "No love in your heart for orcs I see. You really made a mess of that guy.", objectives = "Get in the arena at the Crucible of Carnage and defeat Torg Drakeflayer!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27865] = { id = 27865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crucible of Carnage: The Wayward Wildhammer!", description = "You're going to love this one! The Wildhammer heard you were entering the arena and they're determined to make sure you don't leave it.\n\nTime for some good ol' {race} on dwarf action! Let me know when you're ready to do this!", completion = "No love in your heart for dwarves I see. You really made a mess of that guy.", objectives = "Get in the arena at the Crucible of Carnage and defeat Sully Kneecapper!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27866] = { id = 27866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crucible of Carnage: Calder's Creation!", description = "Grim and gory, this next match is sure to have the crowd groanin' one way or another. Calder Gray has been gathering the bodyparts of defeated challengers and building the perfect champion.\n\nThis thing is the ultimate cobbled collaboration of corpsified combatants. A magnificent mashup of mangled monstrosities. Are you ready to get messy?! Cause I am! Let me know when you're ready so we can get this thing started!", progress = "No payout until the fight's over, man.", completion = "Wow! When I saw that... thing stumble into the arena, I thought you didn't stand a chance. But you proved me wrong. You tore it apart!\n\nGrizzly business.", objectives = "Get in the arena at the Crucible of Carnage and defeat the Cadaver Collage!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27867] = { id = 27867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crucible of Carnage: The Earl of Evisceration!", description = "You're going to have your hands full with this one, pal. We've got a seasoned gentleman warrior here! He hails from Gilneas, and he's out to prove that he's the best warrior this side of Azeroth.\n\nYou better pull up those boots and zip up those pants, because it's going to get downright feral up in here. Give me the word when you're down for some punishment.", completion = "You really pulled that one out. I thought you were done for sure when he wolfed and started tearing up the arena. I guess I should know by now that you don't go down easy.", objectives = "Get in the arena at the Crucible of Carnage and defeat Lord Geoffery Tulvan!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27868] = { id = 27868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crucible of Carnage: The Twilight Terror!", description = "We've got someone you'll really love to hate this time around. I wasn't sure at first if I should let him into the pit, but a fight's a fight! And who am I to turn down some guaranteed cash?!\n\nThis guy hails from the Twilight Citadel itself, and comes toting a toasty punch. Better move fast and watch your back! Just give me the word when you're ready for some action.", completion = "Looks like this title is yours! You really pulled that one out of the fire. \n\nCongratulations. I hope the coin serves you well.", objectives = "Get in the arena at the Crucible of Carnage and defeat Emberscar the Devourer!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27869] = { id = 27869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dragon and the Temple", description = "These serpents must be from the Temple of Atal'Hakkar. I already had a hint...\n\nNot a few days ago, I had a visitor stop by and ask me to keep an eye out for such things. An elf by the name of Itharius. I'm sure he didn't think I could see through his form... he was a green dragon in disguise, come here to help his fallen brothers no doubt.\n\nHe may very well be on to something. Itharius left for the temple itself. Perhaps you'd better go look for him there. Dark things are afoot.", completion = "The goblin sent you? She has a cunning eye, that one.\n\nShe speaks the truth. I am here to stem the tide of corruption seeping from this temple. If you would save your people from a wicked fate, {name}, I ask for your assistance.", objectives = "Speak with Lord Itharius atop the outer steps of the Temple of Atal'Hakkar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27870] = { id = 27870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Marshtide Watch", description = "Regardless of whether you assist me within the temple, your people must be told of what is brewing here.\n\nNorth of the temple, humans of your mortal Alliance have built what they call Marshtide Watch. They war with the Horde across the swamp, a raging conflict that I foresee only worsening.\n\nIt is not my role to interfere in mortal affairs, {name}. I simply ask you bring warning to your people of what lurks within the temple.", completion = "Trouble within the temple... I wish we could spare forces to deal with it. The war with Stonard is already raging, and we need every man we can get.", objectives = "Speak with Joanna Blueheart at Marshtide Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27871] = { id = 27871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Stonard", description = "Regardless of whether you assist me within the temple, your people must be told of what is brewing here.\n\nSouthwest of the temple is the Horde town of Stonard. The orcs there wage war with the new human arrivals to the swamp, a raging conflict that I foresee only worsening.\n\nIt is not my role to interfere in mortal affairs, {name}. I simply ask you bring warning to your people of what lurks within the temple.", completion = "We have no time to send orcs to the temple, {name}. The humans come, and they are many. Stonard must be defended!", objectives = "Speak with Dispatch Commander Ruag at Stonard in Swamp of Sorrows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27872] = { id = 27872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tortolla Hub Complete" }
quests[27873] = { id = 27873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aviana Hub Complete" }
quests[27874] = { id = 27874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aviana's Legacy", description = "Your expertise is needed elsewhere, {name}.\n\nJust southwest of the World Tree you will find the Shrine of Aviana, home to the Druids of the Talon. Aviana, the matron of all winged creatures, gave her life for this world ten thousand years ago.\n\nI sense her shrine is being threatened, as are the druids who guard it. Seek out Choluna, one of the wisest of the winged druids, deep within the shrine.", completion = "Ysera herself sent you to me? Oh! It's a honor to speak with a representative of the aspects.\n\nIt's true that our shrine is in jeopardy. The harpies we once sheltered in our boughs have suddenly turned against us.\n\nBut please, don't rejoin the fight until you are ready. Our shrine is no mere battleground. Use its peace and power to center yourself.", objectives = "Locate Choluna at the Shrine of Aviana in Mount Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27875] = { id = 27875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prayerblossom", description = "I have worked for years to try to cure the affliction of the Broken. The foul energies that corrupted them did  more than twist their bodies; it took the comfort of the Light from them. They cannot feel its warmth.\n\nI cannot let Magtoor pass on in darkness, {name}. Before he worsened, I was studying prayerblossom, a flower that grows in the shifting mire. It grows hardy in even the darkest shade. I beg of you, gather these flowers for me, for Magtoor's sake.", progress = "Have you brought the prayerblossom?", completion = "Prayerblossom has been used by the Broken as a remedy since they settled in this swamp. If it soothes the physical form, it might be used for more powerful healing...", objectives = "Collect 10 sprigs of Prayerblossom from the Shifting Mire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27876] = { id = 27876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Mire", description = "The Shifting Mire takes its name from a unique phenomenon. By some force, the extremely fine silt will collect, and move on its own accord, travelling as if alive.\n\nI originally worried this was some corruptive force, but my studies have shown the opposite; whatever energy invigorates this soil is positive in nature. Perhaps such vibrant life can be imparted onto the Broken to reawaken what they once were.\n\nThe silt may not take kindly to being collected, {name}. But please, help gather it.", progress = "Did you get those samples?", completion = "It will have to be purified, but this will be most helpful. Thank you.", objectives = "Collect 10 samples of Invigorated Silt from Shifting Mireglobs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27877] = { id = 27877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Morons' League", description = "I need your help in a little project I'm working on, {name}.  It falls into a realm I like to call \"defensive archaeology\".\n\nI like to bury non-magical items in conspicuous places to fool those Alliance idiots into thinking they've found something valuable.\n\nHmm... Dark Iron dwarves wander Hammertoe's Digsite and Angor Fortress, to the north.  Bring their heads back to me.  Yes, that's right, their heads.\n\nOnce the flesh is stripped, we can use those skulls to interfere with the dwarves' work.", progress = "<Lidia waits expectantly.>", completion = "Excellent!  We'll bury these immediately.  Those Explorers' League dimwits will never suspect us!", objectives = "Obtain 15 Dark Iron Heads.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27878] = { id = 27878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forcible Acquisition", description = "I've got a little proposition for you, if you're interested.\n\nThe Dark Iron dwarves were here long before we arrived.  That means that, once these titan ruins opened up, the Dark Irons were the first ones in there, looting all the choice items.  I'll bet they've still got those treasures locked up inside Angor Fortress, northwest of here.\n\nI want you to find such a treasure... then steal it.", progress = "Back so soon?", completion = "I knew it!  The High Examiner will be pleased to see this.\n\nNice work, {race}.", objectives = "Search for treasure in the bottom floor of Angor Fortress.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27879] = { id = 27879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Survival of the Fattest", description = "We're hard-up for supplies, stranger.  With the black dragons raining destruction on our hunting grounds, we have no way to get food.\n\nThe ogres to our south, however, have exactly what we need.  Within their grotto you should find plenty of meat and crafting supplies.\n\nThey may put up a fight.  Be on your guard.", progress = "Welcome back.", completion = "I imagine those ogres weren't too much trouble for you.  Here - some coin for your troubles.", objectives = "Obtain 6 pieces of Dustbelcher Meat and 10 sheets of Dustbelcher Silk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27880] = { id = 27880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Half-Ton Holdouts", description = "My grunts have got this dragon problem under control.  Besides, I can't have an upstart {class} like you barging in and ruining our battle plans.\n\nYou want work?  Fine, I'll give you work.  Investigate the ogre camp to our southwest.  From what I've heard, a small army of combatants seems to have appeared outside of their hovel.\n\nWe can't sit and wait for them to flank us, soldier... especially while we're already embroiled with black dragons.  Thin their ranks before they thin ours.", completion = "You've got the hint of a hero in you, {race}.\n\nNow get out of my battlefield.", objectives = "Slay 12 Dustbelcher Combatants. You may kill Dustbelcher Maulers or Dustbelcher Shaman.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27881] = { id = 27881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodwatcher Point", description = "I've got an idea, but it's a bit of a long shot.  Thankfully, long shots happen to be a specialty of mine.\n\nNorth of here, the Reliquary has uncovered a new set of titan ruins beneath the sands.  If there's anything older and wiser than dragons, it's titans.  Heck, I've heard rumors that the titans CREATED the dragons.\n\nTalk to High Examiner Tae'thelan Bloodwatcher at their camp to the northeast.  He'll have more information than I do about these titans.\n\nWhat did I tell you?  It's a long shot.", completion = "Titans?  You come to me, asking about titans?\n\nYou've come to the right place, as we're on the brink of discovering something big.  You will, however, need to earn your keep first.", objectives = "Speak with High Examiner Tae'thelan Bloodwatcher at Bloodwatcher Point in the Badlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27882] = { id = 27882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Not About History, It's About Power", description = "The Explorers' League may have a yeoman's knowledge of the actual act of digging.  What they lack, however, is the good sense to USE the artifacts that they dig up.  They stow their treasures in stagnant museums instead of using these items of power for their true purpose.\n\nThe dwarves are fools.  Fortunately, they die easily.\n\nYou'll find them digging into canyon walls north of here.  Take whatever you can out of their stubby-fingered hands, then return it to me.", progress = "You've returned with liberated artifacts, I presume?", completion = "Chalice... worthless.\n\nVase... counterfeit.\n\nHieroglyph... interesting, but rather common.\n\nWhat's this?  I've never seen trogg craftsmanship of this caliber!  You've stumbled upon something rare indeed, {name}.\n\nWe must not be so hasty as to overlook the troggs.  They may be simple, but they know things about the deep, hidden places of this world.\n\nYou've performed well enough.  Let's talk titans, shall we?", objectives = "Obtain a Broken Chalice, a Dusty Vase, an Earthen Hieroglyph, and a Trogg Tool.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27883] = { id = 27883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warden's Pawn", description = "One of the few items of worth that we managed to loot from these ruins is this small jade statue.\n\nWe believe it to be a key of some sort, but we're unable to determine what it opens.  As such, it is useless to me.\n\nPerhaps you'll have some better luck with it.", completion = "<The statue clicks into place on the large stone slab.>", objectives = "Find a use for the Warden's Pawn within the Tomb of the Watchers in the Badlands.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27884] = { id = 27884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sentinel's Pawn", description = "We found this small red statue on the corpse of one of those Explorers' League archaeologists.  Sadly, it wasn't us who killed him.  The local wildlife had already taken care of that.\n\nThe statue is well-crafted, but apparently bereft of magical power.  You may use it for whatever means you deem necessary.", completion = "<The statue slides into place on the cold marble slab.>", objectives = "Find a use for the Sentinel's Pawn within the Tomb of the Watchers in the Badlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27885] = { id = 27885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warden's Game", description = "You see the statue split into two, then four, then eight identical statues in a square formation.\n\nYou hear a voice, not through your ears, but in the back of your mind:\n\n   \"A true warden does not face OUTWARD, searching for signs of danger.\n  A true warden keeps his gaze INWARD, always focused on protecting his quarry.\"\n\nPerhaps this is a riddle of some sort?", objectives = "Complete the Warden's Game by teleporting the Warden's Pawns into inward-facing positions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27886] = { id = 27886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sentinel's Game", description = "As you place the statue in its place, several other stone statues appear in the room.  One more ruby-colored statue also appears, in a small enclosure on the far end of the room.  You hear a voice:\n\n  \"The Sentinel watches.\n  The Sentinel protects.\n   The Sentinel's vision never falters.\"\n\nThat red statue on the other side of the room looks important.  Perhaps you should try to connect the two red statues?", objectives = "Complete the Sentinel's Game by connecting the two red statues.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27887] = { id = 27887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Protectors", description = "You heard a good amount of rumbling happen in the tomb's central chamber.  Those two large statues did look awfully suspicious.", objectives = "Investigate The Warden and The Sentinel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27888] = { id = 27888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Blam", description = "Inside the chest, you find a small, circular device, resting upon a cushion.\n\nIf there are any titan artifacts to be found here in the tomb, this is it.  You resolve to bring it back to Dr. Blam.", progress = "Well?  Has our long shot paid off?", completion = "Just one tiny little device?\n\nI never did understand those titans.\n\nVery well!  Let's see what this peeper can do.", objectives = "Bring the Eye of the Watchers to Dr. Hieronymus Blam at Agmond's End in the Badlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27889] = { id = 27889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Kargath", description = "<Dr. Blam stares at the egg in awed silence, blinks a few times, then looks up at you.>\n\nD... did you see that?  Incredible!  My titan thing idea worked!  With your help, of course.\n\nWe'll want to get these back to Rhea.  She's not at Lethlor Ravine anymore; it sounds like she blew her cover when she transformed into her true form in front of all those whelps.  She's now in the west, staying at a large Horde establishment dubbed \"New Kargath\".\n\nShe'll be waiting for you.  And for that egg.", progress = "That's some precious cargo you carry there, {name}.", completion = "I'll take that egg out of your hands now.  We need to get this egg incubated... and hidden, quickly.  There are lots of angry dragons looking for this.\n\nIt's good to see you again, by the way.", objectives = "Bring the Purified Black Dragon Egg to Rhea at New Kargath in the Badlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27890] = { id = 27890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bad Dogs", description = "In my haste to escape from Lethlor Ravine, I forgot to tie up one loose end: Nyxondra.  She's free, and she's sounded the alarm among the black dragonflight.  Half the flight is here in the western Badlands, combing for this egg.\n\nI'll take care of hiding the egg.  You're going to take care of some of the more troublesome dragons.  And you'll have help.\n\nI've paid off a couple of mercenaries to help you.  You'll find them inside this inn.", completion = "You're the {race} we've been waiting for?  It's about time you got here.  My legs could use a stretch.\n\nCome on boys!  Let's go kill us some black dragons!", objectives = "Speak with Amakkar at New Kargath in the Badlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27891] = { id = 27891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amakkar, Jack of All Trades", description = "Before we get too crazy with the dragon-killing, let me tell you a little bit about how I fight.\n\nI'm not terribly strong or stalwart like these other two, but I've got a few tricks.  At your command I'll stun your enemies to keep 'em held still.  I also make sure to keep a few potions around for tight spots.\n\nWhy don't we practice fighting together?  Head out into the field, and you can see what it's like to fight with a real orc.", progress = "We're not through yet, {name}.", completion = "I'm looking forward to fighting with you.", objectives = "Use Amakkar's Kidney Shot and Amakkar's Pocket Potion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27892] = { id = 27892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jurrix the Striker", description = "Oh, you want to talk?  Fine.\n\nI'm Jurrix, the only merc here with half a brain.  The only one with any bite to my attacks, too.  The only reason I keep these meat shields around is to keep myself from getting killed.\n\nListen, you're the boss of this operation.  You give the word, and I'll send a fireball right through your target's heart.  If things start getting hectic, I can even warp time a bit so you can fit in a few extra attacks.\n\nWhy don't we go try fighting together?", progress = "We're not quite ready yet.  A little more practice, then we'll get with the dragon-slaying.", completion = "I think you're ready, {name}.  You're getting the hang of this.", objectives = "Use Jurrix's Fiery Blast and Jurrix's Time Warp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27893] = { id = 27893, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gargal, the Behemoth", description = "You may not have noticed, but I'm pretty big, as far as orcs go.\n\nI make sure that my two pals here don't get into too much trouble.  They're small, and they don't have a big shield like me.  I'm big, and I can handle a few monsters hitting me!  Plus, if I'm careful, I can usually get them to hit my shield instead!\n\nI can protect you, too.  Come on, let's go practice for a bit.  I'll make sure the enemies attack me, and not you.", progress = "Don't worry, little {race}.  I'll protect you.", completion = "See?  No need to worry when Gargal is around.  Just let me know, and I'll protect you from the monsters.", objectives = "Use Gargal's Shield Wall and Gargal's Mighty Shout.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27894] = { id = 27894, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wrath of a Dragonflight", description = "Hello, {name}.  It looks like you four have had time to become well-acquainted.\n\nI have my first assignment for you.  Kalaran, an ancient black dragon of considerable power, has joined in the hunt for the egg we are protecting.  We need to stop him before he gets too close.\n\nYou will find him and his minions at the Dustbowl, east of New Kargath.  Hunt him down and defeat him.  You will likely need the help of your new mercenary allies.", completion = "One less dragon to worry about, one step closer to redemption.  Onward, my soldiers!", objectives = "Slay Kalaran the Annihilator and 4 Darkflight Soldiers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27895] = { id = 27895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Their Hunt Continues", description = "The black dragonflight means business.  As you've probably already noticed, they've taken over a large portion of New Kargath.  These troops are under the command of General Jirakka and his champion, Moldarr.  They must be stopped.", completion = "Two more dangerous black dragons have been removed from this egg hunt.  Your greatest task, however, still awaits.", objectives = "Defeat General Jirakka, Moldarr, and 6 Blackflight dragonspawn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27896] = { id = 27896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sorrow and the Fury", description = "My greatest regret is the treatment that we - no, I - gave to Nyxondra.  I forced her to lay eggs, then I performed experiments on them.  Over, and over, and over again.\n\nEven as a mother myself, I can only imagine her sorrow.\n\nNo... I mustn't be weak.  Our work is, after all, for the benefit of future generations of black dragons.  Her sacrifice was necessary.\n\nShe circles the Ruins of Kargath, northwest of New Kargath, insane with fury.  Please, heroes... put her out of her misery.", completion = "Just think... Nyxondra may end up being the mother of the new black dragonflight.  In death, she has given a gift to the future generations of Azeroth.", objectives = "Slay Nyxondra and 12 of Nyxondra's Broodlings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27897] = { id = 27897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hidden Clutch", description = "With the major black dragons out of the Badlands, it is now safe to move the egg again.  You will find me on a small plateau, north of New Kargath.\n\nCome and find me.", completion = "The egg must always be moving.  We are not safe anywhere.\n\nDeathwing, even in his madness, knows all the hidden places in this world.  The egg must not rest.", objectives = "Speak with Rhea at The Hidden Clutch in the Badlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27898] = { id = 27898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rheastrasza's Gift", description = "Wait here.  I will retrieve the egg.", objectives = "Wait as Rhea retrieves the egg from the Hidden Clutch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27899] = { id = 27899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That Gleam in his Eye", description = "If you're looking for Harrison, you just missed him.\n\nHe was going on and on about his latest discovery, and how everything was beginning to make sense.\n\nWhatever... he certainly wasn't making sense to me.\n\nI tried to convince him to stay here and just enjoy a few desert sunsets with me, but there's no talking to him when he gets that gleam in his eye.\n\nPerhaps you'd be willing to check in on him?\n\nHe was headed to that big monolith, south of here.", completion = "It would seem that I'm not the only one interested in these obelisks...", objectives = "Speak to Harrison Jones at the Obelisk of the Sun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27900] = { id = 27900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I've Got This Guy", description = "Good timing, {name}.\n\nSeems I'm not the only one interested in these obelisks, and these fellas aren't inclined to compare notes...\n\nI think I can handle this guy.\n\nMaybe you could take care of a few of his friends before they make their way over here?", progress = "This guy's tougher than he looks - and he looks tough!", completion = "That's a relief. Thanks, {name}.\n\nTurns out I've got my hands full here.", objectives = "Kill 10 Schnottz Air Troopers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27901] = { id = 27901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Don't Know What They've Got Here", description = "Listen, {name}. I don't have a lot of time to talk here.\n\nThese guys are excavating relics from this site and taking pieces of ancient technology that we need!\n\nI need you to check their crates for pieces of an ancient activation device. The officers should have the codes you'll need to open them.\n\nHurry!\n\nWe can't let them load this stuff into their planes!", progress = "Have you got the titan activation device, {name}?", completion = "That's it!\n\nGood work, {name}!", objectives = "Create the Titan Activation Device.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27902] = { id = 27902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Purespring", description = "Magtoor has told me of the shamanism that the Broken practice. The great Nobundo once said that the path of the elements may, in a way, be another way to the Light.\n\nI can only hope there is some truth in this. The elementals that gather near Purespring Cavern to the south are a source of truly pristine water. They can be chaotic and violent, but the pure water harvested from them will be the perfect conduit for the blessing of the Light.\n\nPlease, bring me this water, {name}.", progress = "Have the elements given up their source?", completion = "Such clarity... let us hope this will aid poor Magtoor.", objectives = "Collect 6 Purespring Motes from Purespring Elementals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27903] = { id = 27903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ignition", description = "This guy just won't go down!\n\nYou're doin' great, kid. Only one thing left to do.\n\nAccording to my research, there should be a titan statue down below. Use the device to activate it, then break it down.\n\nIf my theory is correct, that statue holds the key to reactivating this obelisk.", progress = "Time to see if this old mechanism still works...", completion = "According to Harrison's notes, placing the lens upon this dais should re-activate this obelisk.\n\nExactly what that means remains to be seen...", objectives = "Recover the Lens of the Sun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27904] = { id = 27904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breath of Mist", description = "The Grell are forest spirits that wander the Misty Valley to the east. Though they resemble imps, I have found no demonic traces among the ones I've studied. They are, as far as I can tell, uncorrupted. \n\nThose that dwell in the valley move as one with the wind, summoning gusts of breeze at their whim. This pure air may be incorporated into my remedy for poor Magtoor.\n\nPlease, {name}, gather the smoky crystals found within the grells' bodies for me. I must exhaust every potential cure.", progress = "Do you have the crystals?", completion = "I can only hope this will lead to a cure, {name}. Thank you for bringing it to me.", objectives = "Collect 5 Smoky Crystals from Misty Grell.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27905] = { id = 27905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tailgunner!", description = "Okay, I've softened this guy up, how about you help me finish him off?\n\nI've got a plan for our escape, but it'll require a lot of guts and a little luck.\n\nYou up for it, {name}?\n\nJust follow my lead...", completion = "Good work back there, {name}.\n\nLooks like we've lost them, for now at least.", objectives = "Use the tailgun to defend the Schnottz Bomber.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27906] = { id = 27906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neeka Bloodscar", description = "There is much work to do in recovering from the assault and bracing ourselves for the next one. I will need coordination from all of our scouts.\n\nNeeka Bloodscar is our finest tracker, trained in the harsh Badlands. She has been sent west to Splinterspear Junction to watch for Alliance activity.\n\nGo to Neeka, {name}. Tell her of what has occured in Stonard. Assist her in any way she requires.", completion = "I hope the sight of my sniveling amuses you, {name}. It will be the only joy here.", objectives = "Speak with Neeka Bloodscar at Splinterspear Junction.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27907] = { id = 27907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prayerblossom", description = "I have been ruined, {class}. I placed my strength in Helgrum, and now it bleeds from his gaping wounds. Wounds too deep to heal, flesh that refuses to knit.\n\nHe murmurs in fear, consumed by fever and pain. I cannot leave his side. Not now. Please, I ask you in shame to gather herbs for me.\n\nThe prayerblossom that grows in the swamp is an old remedy for soothing. With enough of it, his pain might be stilled.", progress = "Have you brought the prayerblossom?", completion = "I will grind these and try to get him to eat. Thank you.", objectives = "Collect 10 sprigs of Prayerblossom from the Shifting Mire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27908] = { id = 27908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Mire", description = "Helgrum's wounds fester in the swamp air. They swell and ooze, filling his final moments with suffering. I must have something to coat them with.\n\nThe spirits move through this mire. They inhabit the mud itself, pushing it along in clumps of fine soil that take on lives of their own\n\nThe spirits of the cool, pure mud will offer him some comfort. Please, gather it for me, for I cannot abandon his side.", progress = "Helgrum still breathes. Do you have the mud?", completion = "At least I can soothe him with my own hands while he still breathes. Thank you, {name}.", objectives = "Collect 10 samples of Invigorated Silt from Shifting Mireglobs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27909] = { id = 27909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Purespring", description = "Helgrum's breathing slows. His time is near.\n\nI need water. Elementals roam the ponds of Purespring Cavern. The water that flows from them is the purest in this swamp.\n\nEven if I could risk leaving Helgrum's side, my axe would shudder in my hand. I must beg you once again to pity me, for his comfort. Bring me the motes of the elementals, that his final drink may be pure and refreshing.", progress = "You've returned.", completion = "He can only drink so much. The rest might be used for washing his body, after...\n\n<Neeka glares in frustration and shudders, turning her head away.>", objectives = "Collect 8 Purespring Motes from Purespring Elementals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27910] = { id = 27910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last Regrets", description = "If I am reduced to groveling, I may as well ask everything I can. There is one last favor I would ask of you, one more task a shamed orc pleads for.\n\nHelgrum had a prized prey. Duskfang, eater of ogres, the great panther of Misty Valley. He would never allow himself the leisure of stalking it. Though he wanted badly to hunt, our scouting duties were too important.\n\nIf he cannot hunt Duskfang in this world, he can hunt the beast in the next. Take up the hunt for him; bring Duskfang's pelt to me.", progress = "Has Duskfang shown himself?", completion = "With Duskfang to shroud his body, he will carry the animal's spirit with him into the afterlife.\n\nListen to me. An old superstitious fool. I'm so sorry, Helgrum...", objectives = "Collect Duskfang's Hide.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27911] = { id = 27911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "With Dying Breath", description = "He stirs...\n\nDo not leave, {name}. Please, honor Helgrum with me. You have done so much for him.", completion = "He is gone.\n\nHe is right. I must be strong for him...", objectives = "Witness Helgrum's last moments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27912] = { id = 27912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Titans' Trove", description = "As the second defender falls to the ground, a chest appears in the back of the chamber.  Could this be what they were protecting?", completion = "You peer into the chest...", objectives = "Investigate the Trove of the Watchers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27913] = { id = 27913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Titans' Trove", description = "As the second defender falls to the ground, a chest appears in the back of the chamber.  Could this be what they were protecting?", completion = "You peer into the chest...", objectives = "Investigate the Trove of the Watchers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27914] = { id = 27914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessing of the Green Dragonflight", description = "You have done well, {name}. Jammal'an may have escaped our grasp, but his retreat paves the way for me to enter the temple as I desire.\n\nStay where you are and do not move. I will hasten your return by pulling your spirit to me through the Emerald Dream.\n\nThis may cause slight drowsiness.", completion = "You have performed a great service for me and my kind, {name}. Accept this as a symbol of my gratitude, and of your courage.", objectives = "Speak with Lord Itharius atop the Temple of Atal'Hakkar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27915] = { id = 27915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heart of the Temple", description = "I must confess I have a more personal involvement in this affair. One of the first of the green dragons corrupted here was my brother, Eranikus.\n\nI thought Eranikus gone, lost forever to the darkest rifts of nightmare, but I have heard that his shade has emerged within the temple. I know not whether it is truly him, or an empty, mournful echo.\n\nIf you wish to help me further, return to the Hall of Masks and journey through the archway into the true sanctum of the temple. I will find you there.", completion = "I am pleased to see you once again, {name}. You are truly noble to assist me further.", objectives = "Speak with Lord Itharius again inside the Temple of Atal'Hakkar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27916] = { id = 27916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruag's Report", description = "Here is Ruag's report, {name}. Let him know his scout is still here.\n\nDo not speak of Helgrum. I will not distract others with news of tragedy.\n\nI have to be strong. We all have to be strong.", progress = "Yes?", completion = "<Ruag reads over the report.>\n\nI see.  Thank you for this information, {name}.", objectives = "Deliver the Splinterspear Report to Dispatch Commander Ruag in Stonard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27917] = { id = 27917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sniffing Them Out", description = "I could smell Godfrey and his companions a mile away from here. They did an exceedingly poor job covering their tracks in flight. It will be the mistake that puts the final nail in their coffins.\n\nOne of them is very close, and though the scent has changed slightly in undeath, I'm fairly certain it's Ashbury's. Go inside and tear him to pieces, we'll ensure the Forsaken do not intervene with our task.", progress = "Kill Ashbury before I lose my patience. You wouldn't like me when I'm angry...", completion = "The scent of freshly spilled traitor blood fills my nostrils, and it is absolutely invigorating. However, my bloodlust will not be sated until Godfrey lies on the floor as a lifeless heap.\n\nHe thinks an army of mindless corpses can stop the wrath of the Bloodfang? We'll gnaw on their bones for years to come after our work is done!", objectives = "Kill Baron Ashbury.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27918] = { id = 27918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Harborage", description = "Anchorite Avuun is one of our uncorrupted brethren, what other races know as Draenei. He came to The Harborage to heal us, and try to find a cure. It is he who sent me here to collect these crystals.\n\nHe watches over a very sick friend now... and despite sending word to the Exodar itself, he has not found any aid so far. Could you bring these crystals to him, {name}? You may be the only one able to assist him.", completion = "Thank you, {class}. I am afraid it may be too late... but I refuse to give up, even if the Exodar itself does not hear my cries.", objectives = "Deliver the Draenethyst Crystals to Anchorite Avuun.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27919] = { id = 27919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onward to the Blasted Lands", description = "We appreciate your assistance here in this swamp, {name}.  I would like to inform you that I have received correspondence from Nethergarde Keep.\n\nEnohar Thunderbrew has requested help in investigating the shipwrecks of the Red Reaches, but we have had none willing to make the journey, and I could not leave the Harborage.\n\nNethergarde Keep sits in the Blasted Lands, south of the Swamp of Sorrows.  Do not journey too close to Stonard on your way.", completion = "Ah, has Avuun sent ye? Good, good...", objectives = "Journey to the Blasted Lands and speak with Enohar Thunderbrew in Nethergarde Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27920] = { id = 27920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armored to the Teeth", description = "We've hit an unexpected snag in our assault on the keep, {name}. It seems the servants that tended to Baron Silverlaine and Commander Springvale in life do so now in death as well, and Godfrey has placed them directly between us and him.\n\nNot to worry, we won't let them be anything more than a minor inconvenience. Eliminate Silverlaine and Springvale both and not only will their guards no longer have masters to direct them, it will place us that much closer to our final goal.", progress = "It is infuriating that we have to kill these ghost soldiers when they are completely outside the main objective, but it must be done. Godfrey is a cunning foe indeed.", completion = "We're nearly there, {name}. The time is now to charge further ahead and take out Walden!", objectives = "Kill Baron Silverlaine and Commander Springvale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27921] = { id = 27921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fighting Tooth and Claw", description = "It appears that Lord Walden has finally taken notice to our presence and has heightened his defenses. It's worthless really... nothing will deter our pack.\n\nThe path ahead to him is rife with powerful Scourge minions, but I trust that you will be able to clear the path for the rest of us to follow in. Once we kill Walden, it should be a straight shot to his cowardly leader.", progress = "We're behind you, {name}.", completion = "<Packleader Ivar Bloodfang grins, revealing his razor-sharp teeth.>\n\nIt won't be long now before the entire keep is ours, thanks to your valiant efforts.", objectives = "Kill Lord Walden.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27922] = { id = 27922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traitors!", description = "Please, stranger.  You must help me.\n\nI came here to investigate the arrival of a powerful ally to the Neferset, only to be betrayed by my closest allies and given up to the enemy.\n\nGo to the terrace above us to the east and find the information I failed to uncover.  You'll need to hide from the Neferset.  Perhaps you can hide behind one of the large plants on the platform to conceal your presence.\n\nDo this for me and I will help your friends find their way to safety.", progress = "What did you witness, {name}?", completion = "A djinn!  We must escape as soon as possible.\n\nThis unholy alliance of the Neferset with the minions of Deathwing does not bode well for us.", objectives = "Hide behind the Neferset Frond and Uncover the Neferset Secret.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27923] = { id = 27923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smoke in Their Eyes", description = "I'm not sure what knuckle-headed plan your friend is concocting, but we're going to need a distraction if we're to stand a chance of escaping.\n\nTake the torch from that brazier and go start some fires.\n\nPerhaps if we divert the Neferset scum's attention away for a few minutes, we'll have the opportunity we need.", completion = "Yes.  I hear the Neferset calling each other to the east.  This might yet work.", objectives = "Burn Stacks of Hay inside the Lost City of the Tol'vir in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27924] = { id = 27924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Budd's Plan", description = "I've an idea!  Trust me, it's a good one this time!\n\nGet some of those shiny armor pieces the cat-people wear.\n\nThis plan cannot fail.  Trust me.", progress = "Did you get the pieces, {name}?", completion = "Excellent.  You'll see, this can't possibly go wrong!", objectives = "Obtain 6 pieces of Neferset Armor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27925] = { id = 27925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Efficient Excavations", description = "This manual describes outlandish theories on how to efficiently manage large groups of workers as they engage in the manual labor of various types of excavation.\n\nIt becomes clear to you that the author of the book is the figure in charge of the over-aggressive pillagers here.\n\nPerhaps an introduction is in order.", objectives = "Bring 'Efficient Excavations' to Belloc Brightblade in Schnottz's Landing.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27926] = { id = 27926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eastern Hospitality", description = "The commander is quite busy now, I'm afraid.\n\nThe demands of an operation such as this require much of his attention these days.\n\nWhile you wait to speak with him, why don't you mingle with some of our guests?\n\nWe have invited a variety of Azeroth's most illustrious figures to be present when we unlock the secrets of this region.\n\nI am confident that you will find them most captivating.", completion = "I trust that you had no troubles fitting in with our guests, hmm?", objectives = "Belloc Brightblade wants you to mingle with the guests at Schnottz's Landing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27927] = { id = 27927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down to the Scar", description = "The Badlands are home to some unusual people, many of whom have been here for quite a long time.\n\nFor example, there were three gentlemen who were staying here in town.  I forget their names... the dwarf was Theldurin, I think?  Anyhow, they headed south with a pack full of ale a couple of days ago, and haven't been heard from since.  I think they were headed to that big scar.\n\nWould you mind checking in on them?  I'd like to make sure that they're alright.", completion = "They sent you to check up on us?  Pshh... I've been around this desert longer than any of those chumps.  We're just soaking in some of the scenery and telling stories about old times.\n\nYou like telling stories?", objectives = "Find Theldurin the Lost at the Scar of the Worldbreaker in the Badlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27928] = { id = 27928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Favor for the Furrier", description = "The commander can be most generous to those who demonstrate their loyalty, and I know of something that you can do to curry favor with him.\n\nBefore building up his... ehh... workforce, he dealt in the furs of animals.\n\nHe is quite skilled in the art of leatherworking. The furrier can do wonders with even the most tattered pelts.\n\nThe dried oasis to the east is said to be home to a rare breed of coyote.\n\nTheir furs would make a very thoughtful gift.", progress = "Were you successful in your hunt?", completion = "Oh, these are exquisite!\n\nThe commander will be able to make a winter uniform with these.", objectives = "Collect 5 Desert Coyote Pelts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27929] = { id = 27929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drag 'em Down", description = "A single Dragonmaw drake is worth a dozen Wildhammer gryphon-riders. Take them off of their lice-ridden birds and they're nothing.\n\nEven you can slay them easily, Horde-{class}.\n\nHunt gryphon riders flying over the river north of Bloodgulch. Take this hook and fling it at them as they fly by. Their momentum will hurl them from their mount, right to your feet. Finish them! Kill a few Thundermar gryphon riders and I'll believe your Horde is as mighty as you say.", completion = "You look a little battered. Those dwarves didn't give you any challenge, did they?\n\nStill, that was an impressive show.", objectives = "Use the Barbed Fleshhook to dismount and kill 4 Thundermar Gryphon Riders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27930] = { id = 27930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Devastation", description = "The coast is clear.  If Rheastrasza or the egg were able to miraculously evade Deathwing's flames, they would probably need your assistance as soon as possible.", completion = "Heroes:\n\nIf you are reading this, then my suspicions were correct.  Deathwing has found us.  The egg is destroyed, as am I.\n\nThis was, actually, the plan from the beginning.  You see... the egg that Deathwing destroyed was not the egg he sought.\n\nIt was mine.", objectives = "Search for Rheastrasza.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27931] = { id = 27931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Quaking Fields", description = "Before you can help us here, you're going have to deal with Therazane, the Stone Mother's, forces to the south. The elementals and giants upon the Quaking Fields are being mustered.\n\nThey too are after the middle fragment of the World Pillar. They'll attack us amidst our war with the stone troggs and we'll be unable to repel them.\n\nI've sent the arch geomancer ahead. Get to Slate Quicksand and do as he asks.", completion = "Good, {race}, you're here.\n\nWe'll have to act fast if we're to prevent Therazane's forces from attacking.", objectives = "Speak with Slate Quicksand at the Quaking Fields in Deepholm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27932] = { id = 27932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Axe of Earthly Sundering", description = "The emerald colossi are the greatest of the Stone Mother's creatures. They must be the first to be removed from the field.\n\nI brought Stonefather Oremantle's axe for just this task. Use it to sunder the giants.\n\nThat should bring them down to a more manageable size for you to finish off.", completion = "Thank you, {name}. Without all of their giants, Therazane's forces will have a harder time taking Stonehearth.\n\nNow, if you please, hand back the axe. I'll keep it safe until you can rescue the Stonefather.", objectives = "Slay 5 Sundered Emerald Colossi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27933] = { id = 27933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Ore", description = "You're going to have to deal with the leader of Therazane's forces here. However, to get you to him quickly and safely, I'm going to need to perform a ritual.\n\nGo out into the field and collect elemental ore from the ragers. With enough of it, I should be able to make you one with the ground to get you where you need to go.", progress = "Have you all that is required?", completion = "These should do. I'll just need a moment to prepare the ritual.", objectives = "Collect 6 Elemental Ore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27934] = { id = 27934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One With the Ground", description = "The leader of the Stone Mother's forces here is the great earth elemental lord, Avalanchion. Luckily for us, the Twilight's Hammer cultists have decided to invade his lair. They're seeking to bind his elementals to their will.\n\nWe will take advantage of the chaos. The earth ritual that I invoke will make you one with the ground. It will take you near to Avalanchion without alerting him to your presence.\n\nIt's up to you to finish him.", objectives = "Complete the One With the Ground ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27935] = { id = 27935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Down the Avalanche", description = "Avalanchion stands before you. Slay him to keep Therazane's forces from attacking Stonehearth.", completion = "You've done what few others could have. Defeating Avalanchion was no small feat.\n\nI'm impressed, {name}. Will you help us with our war against the stone troggs so that we can rescue the Stonefather?", objectives = "Slay Avalanchion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27936] = { id = 27936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Down the Avalanche", description = "You have to go back and slay Avalanchion to keep Therazane's forces from attacking Stonehearth!", completion = "You've done what few others could have. Defeating Avalanchion was no small feat.\n\nI'm impressed, {name}. Will you help us with our war against the stone troggs so that we can rescue the Stonefather?", objectives = "Slay Avalanchion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27937] = { id = 27937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hero Returns", description = "The Stonefather is waiting for you back south at Stonehearth.\n\nMake yourself presentable. You've earned a hero's welcome!", completion = "Our hero returns!\n\nYou have saved my people, {name}. You have earned that which you seek.", objectives = "Present yourself to Stonefather Oremantle at Stonehearth in Deepholm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27938] = { id = 27938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Middle Fragment", description = "I present you with the key to Stonehearth. With it you may unlock the vault to my home and recover the middle fragment of the World Pillar.\n\nKeep the fragment safe, {name}. Make certain to get it to the Temple of Earth in the middle of Deepholm as quickly as possible!\n\nKnow that you are always welcome here.", progress = "You've returned. Did you recover the middle fragment?", completion = "The Middle Fragment of the World Pillar!\n\nThank you, {name}. I can only imagine what you had to go through to get this to us. I'll see to it that it's placed within the center of the chamber.", objectives = "Recover the Middle Fragment of the World Pillar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27939] = { id = 27939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Desert Fox", description = "Zhere is much to be done in zhis region, {race}.\n\nVe bozh haf a burning passion for zhe ancient technologies here, do ve not?\n\nPerhaps zhere is a vay for us to vork togezher?\n\nLet us put zhe misunderstandinks of zhe past behind us zhen, hmm?\n\nNow, zhere is an elusive animal in zhe region to zhe east zhat I have been huntink. Brink me zhis creature as a token of your sincerity, hmm?\n\nZhen maybe I let you in on my operation...", progress = "Have you captured zhe Desert Fox, {class}?", completion = "You've done it!\n\nPerhaps I can trust you vizh more serious matters, hmm?", objectives = "Schnottz wants you to bring him the Desert Fox.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27940] = { id = 27940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dirty Birds", description = "The sky above the Shriveled Oasis is littered with these nasty vultures.\n\nLike infectious rodents with wings, these creatures serve no great purpose and inflict untold misery.\n\nRid the skies of this nuisance and leave the region better than you found it.", objectives = "You are to slay 8 Diseased Vultures.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27941] = { id = 27941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fashionism", description = "We have a strict policy among our ranks, one that we take most seriously.\n\nOur troops are to dress in official uniform at all times. This helps with organization, friendly fire incidents are reduced, and it keeps the troops looking wonderful!\n\nWe call it, Fashionism.\n\nWe've been running low on uniforms lately. I must ask that you recover them from the troopers that have fallen in the line of duty.\n\nYou should find plenty of the poor fellows east of here, at the Ruins of Ammon.", progress = "Were you able to recover the uniforms we need?", completion = "Most efficient work, {class}.\n\nYou should rise rapidly through the ranks.", objectives = "Belloc Brightblade wants you to collect 10 Trooper Uniforms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27942] = { id = 27942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Idolatry", description = "Zhere is somezhink I need handled, {race}.\n\nMy most trusted advisor has run afoul of an ancient curse. A hex zhat has transformed zhe man into a turkey, of all zhings!\n\nI haff studied for days to discover a remedy for his condition, and finally I am ready to conduct zhe ritual.\n\nI vill reqvire several idols from zhe nearby ruins. You are to brink zhem to me at vonce!\n\nDismissed!", progress = "Haff you brought me zhe idols, {race}?", completion = "Zhese look to be of sufficient quality.\n\nVizh zhese, ve are vone shtep closah to zhe cleansink ritual.", objectives = "Commander Schnottz wants you to collect 8 Well-preserved Idols.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27943] = { id = 27943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angered Spirits", description = "Doctor Venkman vas vone of my greatest researchers, until he had to be put out of my misery.\n\nHe did leave me vizh vone of his greatest accomplishments, zhough. Against zhe properly attuned supernatural adversary, zhis veapon vill siphon zhe target's essence.\n\nIt is of key importance in zhe ritual I vill be attemptink.\n\nVhere do you come in, you ask? Simple. You have zhe priviledge of collecting zhe material.\n\nZhe veapon is calibrated to vork on zhe Furious Specters in zhe temple to zhe east.", progress = "Vell, little man? Vere you successful?", completion = "Very goot!\n\nYou have earned yourself a place at zhe ritual.\n\nYou shall be among zhe first to velcome Gobbles back to his... original form.", objectives = "Commander Schnottz wants you to use the L.P.A.C. to collect 5 Furious Spectral Essences.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27944] = { id = 27944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thinning the Brood", description = "We have been trying to get a foothold in The Darkwood for weeks now but that forest is infested with spiders.  Do me a favor and see if you can thin them out enough for us to set up an attack.\n\nCareful out there, I have heard reports of Horde troops nearby earlier in the week.", completion = "Nice work on those spiders {name}.  At this rate, we will be taking that forest in no time.", objectives = "Kill 12 Darkwood Lurkers in The Darkwood. The Darkwood forest is just west of here, across the bridge on the central island.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27945] = { id = 27945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paint it Black", description = "The ground bleeds, {class}. They tear it open, as one would gouge flesh.\n\nThese cultists relish their secrecy but the very elementals they use for their misdeeds can betray them. Seek out Obsidian Stoneslaves northeast of here, among the ruined earth we have named the Black Breach.\n\nShatter their bodies and find for me a perfect heart of black diamond. I will look into this heart. And I will bare its soul.", progress = "The heart. A stone heart, of purest black. Have you found one?", completion = "<Mallia removes her eyepatch and holds the black diamond before her empty eye socket.>\n\nWhat have we, what have we - breaches, the breaches number three. Two heads, one wholly given to its master. I see the future. A hammer united. A mountain shattered. Oh - OH!\n\n<Mallia drops the diamond to the floor, covering her face with her hands.>", objectives = "Acquire a Black Diamond Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27947] = { id = 27947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Vision of Twilight", description = "Cho'gall keeps track of his minions through powerful magical orbs: \"The Eyes of Twilight.\"\n\nIn Mount Hyjal, the Guardians of Hyjal managed to find and manipulate one to their own ends. We must do the same. I want one of those orbs, and I want to use it to peer into the very heart of Cho'gall's lair.\n\nSearch the Black Breach, across the river to the northeast, and find an Eye of Twilight. Do whatever you need to bring it back to me!", completion = "<The Eye sits before you, humming ominously with dark energies.>\n\n<Without warning, the orb rotates, as if to look at you. You sense a malevolent presence, as though the orb is alive.>", objectives = "Locate an Eye of Twilight within the Black Breach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27948] = { id = 27948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sticky Task", description = "Finding supplies on the island has been difficult, to say the least.\n\nFortunately, we have found a good supply of silk in The Darkwood, just west of here.  The bad part of this story is that the silk comes from the glands on Broodmother spiders.  I need you to gather 4 of these for me.\n\nThat should be just enough to finish up this last set of shirts.", progress = "Were you able to gather the sticky silk glands?", completion = "These glands will do nicely.  We are grateful for your help, {name}.", objectives = "Collect 4 Sticky Silk Glands from Darkwood Broodmother spiders in The Darkwood. The Darkwood forest is just west of here, across the bridge on the central island.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27949] = { id = 27949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forgotten", description = "Many soldiers died on this island {name}.  It is only fair that we pay our respects to them in any way that we can.\n\nI need you to travel to Forgotten Hill, due west of here and release our brothers in arms' tortured souls away from this place.  Do be careful over there, reports of undead have been ongoing in the area.", progress = "Were you able to release our forgotten brothers in arms?", completion = "May their souls rest in peace.", objectives = "Release the spirits of 6 tortured souls at Forgotten Hill. Souls can be channeled by touching your hands directly to the gravestones. Forgotten Hill is due west of here, past The Darkwood and The Restless Front.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27950] = { id = 27950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gobbles!", description = "At last! Zhe time has come to set my Gobbles free of zhat nasty curse!\n\nPay attention now, {race}, and stay on guard. Zhere can be no interruptions vhile I perform zhe ritual.\n\nLet me know vhen you haf secured zhe perimeter!\n\nNow, move it!", objectives = "Schnottz wants you to speak with him when you are prepared to witness the ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27951] = { id = 27951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We All Must Sacrifice", description = "<The eye speaks to you, its 'voice' reverberating as if coming from everywhere at once.>\n\nYou seek my sight, {race}? My powers come at a price. These disciples of the Twilight have been honoring me with the blood of Wildhammer dwarves from the nearby ruins, but still I thirst. Perhaps you can do better.\n\nSlay my old masters, and my vision is yours. Honor me with the slaughter of the Shaman of the Black. Blood is blood, after all.", progress = "I have been watching you, {race}.", completion = "<The Eye glimmers darkly, colors swirling about its dusky surface.>\n\nAh, the succulent thrill of life extinguished. Do you feel it, {class}? Do you relish it as I do?\n\nNo, I see not. You fight to protect the lives of others. Pity.", objectives = "Slay 10 Shaman of the Black.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27952] = { id = 27952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Explorers", description = "We have a contingent of the Explorers' League in the chamber just to the northwest inside the temple.\n\nThey've been making increasing noises about something that the Twilight's Hammer is up to.\n\n{name}, would you be a dear and see what they need?", completion = "Oh gosh! Someone's finally here to help us?", objectives = "Speak with Explorer Mowi at the Temple of Earth in Deepholm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27953] = { id = 27953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Reliquary", description = "We have a contingent of the Reliquary in the chamber just to the northeast inside the temple.\n\nThey've been making increasing noises about something that the Twilight's Hammer is up to.\n\n{name}, would you be a dear and see what they need?", completion = "Ah, it's about time someone came to speak with us on matters most urgent.", objectives = "Speak with Examiner Rowe at the Temple of Earth in Deepholm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27954] = { id = 27954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eyes Have It", description = "Very well then, {race}. You have purchased my services in blood. Take me back to Garona Halforcen.\n\nOh yes, I already know where you're taking me. Garona's relentless quest for vengeance is no secret. It will be a delight to watch it unfold.", progress = "Did you have any luck within the Black Breach?", completion = "You found one? I've been searching everywhere. Give it here!\n\nSome of these eyes are won over with riddles or verse. Others require magic. What did this one demand? Ah, it's no matter. What matters is that it's ours.", objectives = "Take the Eye of Twilight to Garona Halforcen at Bloodgulch in Twilight Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27955] = { id = 27955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eye Spy", description = "This terrible thing makes my hair stand on end. Cho'gall uses these to control his minions - now it's time to use it against him.\n\nLet me see... hmm, it's all cloudy. All I can see is you. Why is it showing me you?\n\n<Garona sets the eye out in front of her.>\n\nLook into the eye and tell me what you see. Peer into Cho'gall's lair! What is he doing? Is he heavily guarded? Tell me!", completion = "You've gone pale, {class}. What did the Eye show you?\n\nYou saw Cho'gall? Wait - Cho'gall saw you? He's watching us? He's watching us right now!?\n\nDamn this stupid dark magic! I'm going to have to infiltrate Cho'gall's stronghold myself.", objectives = "Peer into the Eye of Twilight for Garona.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27956] = { id = 27956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunk's Task", description = "Lunk came from the Badlands.  Other ogres try to make Lunk fight.\n\nLunk hate fighting.  Lunk want to learn.\n\nLunk sees machines to the south.  Machines made of gears.\n\nMaybe if you ask nicely, machines will give you some gears?  Then maybe Lunk can have a gear, and learn about machines too.", progress = "You get gears?  How you get them?", completion = "You didn't... KILL the machines to get these, right?.\n\n<Lunk looks upset.>\n\nRight?", objectives = "Obtain 15 Tempered Flywheels from Tempered War Golems.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27957] = { id = 27957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunk No Kill", objectives = "No!  You are the same as Thorium Brotherhood dwarf.\n\n\"Kill dwarf.  Kill spider.  Kill machine.  Kill, kill, kill.\"\n\nLunk come to gorge to go on adventure, not to go on murder spree.\n\nGoodbye, {race}.  You kill too much.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27958] = { id = 27958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Proper Antivenom", description = "Shame that Lunk left.  I was beginning to enjoy his company.\n\nOh well, back to work!\n\nI'm the closest thing that this expedition has to a medical officer, and I'm running low on antivenom.  We tend to need a lot of antivenom.\n\nThe key to a proper antivenom is ALWAYS to start with the poison itself.  The glassweb spiders nearby should be a good place to start.  If you kill them, you can probably extract some venom from the sacs within their jaws.", progress = "Well well, you certainly operate quickly!  You do have the venom, right?", completion = "This... this is way more than I expected.  This will last us for months!", objectives = "Obtain 14 samples of Glassweb Venom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27959] = { id = 27959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunk's Adventure: Spider Rider", description = "Lunk sees you like to kill things.  Let Lunk teach you another way.\n\nLunk always wanted to ride on spider's back.  Looks like fun.  Spiders move too fast, though.  Always slip away.\n\nWe work together.  You fight spider until it gets weak and tired.  Then Lunk jump on spider's back and ride around.\n\nMaybe Lunk even gather some venom for you!  No have to kill!", objectives = "Weaken 7 Glassweb Spiders so Lunk can ride them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27960] = { id = 27960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fewer, the Better", description = "I'm not much of a fighter... I'm more of a mining dwarf.  Same goes for Jack and Pris.  And Lunk... well, you'd think he'd be a big fighter, but he's the biggest wimp of all of us.\n\nWhat I'm saying is, it's good that you came here when you did.\n\nIt seems likely that we in the Thorium Brotherhood are going to be fighting the other Dark Iron dwarves soon.  I'm thinking we should pick off some of their finest before the war starts in earnest.  Start with the geologists and watchmen to the south.", progress = "The fewer of them that remain, the better our prospects are.", completion = "Thank you.", objectives = "Slay 10 Dark Iron Geologists or Dark Iron Watchmen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27961] = { id = 27961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of Place", description = "The gorge is an unforgiving place.  We don't get a whole lot of fuzzy wildlife wandering around here.\n\nWe tried bringing in some wild game, but they haven't fared well at all.  There's just no food for them to eat.  Now the nearby spiders - which were already dangerous - are getting big and fat on chicken meat.\n\nWe'll never get rid of all the spiders, but we can salvage what few chickens remain.  Not only will you be feeding the Brotherhood, you'll be saving them a painful death by spider bite.", progress = "Those poor animals.", completion = "You've got quick hands if you were able to gather this many in such a short time.\n\nExcellent work, {name}.  I'll make sure these ones don't go to waste.", objectives = "Obtain 8 Ash Chickens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27962] = { id = 27962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lumbering Relic", description = "Margol the Rager's an old thunder lizard seen round these parts.  Legend has it that he's been here in the gorge since before it was even a gorge.  Legend also has it that he ate my brother Barnabas.\n\nI don't care how old he is or what kind of magic he shoots out of his nose.  I just want him dead.  For Barnabas' sake.\n\nYou'll find him wandering the cliffs to the south of here.", progress = "Bring me the horn, {name}.", completion = "Yup, this was Margol's horn alright.  No doubt about it.\n\nBarnabas was a digger, like me.  He never stood a chance in combat against the beast.  I'm glad you were here to set things right.", objectives = "Obtain Margol's Gigantic Horn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27963] = { id = 27963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Master... But Who?", description = "You've arrived just in time.\n\nHere's the skinny: the Dark Iron dwarves in the gorge have been acting strangely, and the Thorium Brotherhood intends to find out why.  Overseer Oilfist doesn't like surprises.\n\nWe suspect that they're following orders from some new leader.  I have reason to believe that Gravius Grimesilt, just south of here, knows who it is.\n\nEven here in Searing Gorge, we've begun to hear tales of your exploits, {name}.  You should have no problem with Grimesilt.", progress = "Any news?", completion = "Let's see... Overseer Maltorius... we're quite familiar with him and his work.\n\nWhat's this?  The \"archduke\"?  That sounds promising.", objectives = "Obtain the Dark Iron Memo from Gravius Grimesilt at Grimesilt Worksite.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27964] = { id = 27964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dig-Boss Dinwhisker", description = "Grimesilt wasn't as high up on the chain as I thought.  We'll have to take out his superior and find out what he knows.\n\nDig-Boss Dinwhisker's his name, and he runs the Dark Iron digging operations within the Cauldron, just northwest of here.  His excavators and footmen patrol the eastern side of the Cauldron, digging downward, day and night.\n\nHe's not known to show his face out in the field very often, but if you slay enough of his men, he'll be forced to come out and deal with you.", progress = "If Dinwhisker doesn't have what we seek, I'm not sure what we'll do next.", completion = "A... an ember?  What is this thing?", objectives = "Kill Dark Iron Excavators and Dark Iron Footmen within the Cauldron until Dig-Boss Dinwhisker appears. Then slay Dig-Boss Dinwhisker and obtain his Dark Ember.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27965] = { id = 27965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thorium Point: The Seat of the Brotherhood", description = "Did... did you see that?  This is the missing piece we've been looking for!  We have to take this information back to someone at Thorium Point.\n\nThe Dark Irons have been known to consort with the firelord in the past, but never before have they brought their kind this far out into Searing Gorge.\n\nThorium Point is west and north of here.  You will find it nestled in the cliffs that overlook Pyrox Flats.  Take this information straight to Overseer Oilfist.", completion = "Do I know you, {race}?\n\n\n\nSounds like another one of Ragnaros' minions.  I don't like the sound of that.", objectives = "Report to Overseer Oilfist at Thorium Point in Searing Gorge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27966] = { id = 27966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salvaging the Remains", description = "Forgotten Hill has been overrun with zombies and ghouls ever since we reclaimed this wretched isle.  We have tried to clear them out many times but they always seem to come back.\n\nOne of our lieutenants recommended taking the ghouls' bones when we kill them in hopes that they can't reincarnate overnight.  Think you can help us out with this one?", progress = "Were you able to recover the femur bones?  Better for you to try than me.", completion = "I didn't think you would be able to do it, {name}.  You are just full of surprises aren't you?", objectives = "You need to recover 9 Cursed Femur bones from the ghouls that inhabit Forgotten Hill. Forgotten Hill is on the west side of the island, just past The Forgotten Front.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27967] = { id = 27967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Lieutenant Connor", description = "The first time I heard about Lt. Connor, I was just a young recruit in the Stormwind stockades.  None of us could believe he ended up here on Tol Barad.  Sadly, he still roams these wretched islands, wreaking havoc on our troops morale.\n\nI need you to put an end to his misery... and ours.", completion = "Hey, you made it back alive!  Can't say you were the first one to try this task, but you are definitely the first one to make it back alive.", objectives = "Find and kill First Lieutenant Connor at Forgotten Hill. You will find Forgotten Hill on the far west side of the island.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27968] = { id = 27968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fury of the Pack", description = "Ah, the sweet scent of victory! My men should be tearing Godfrey to pieces even as we speak. Go up to his domain and collect your share of the spoils - you've earned it!\n\nYou'd think that he would have been more difficult to defeat...", progress = "Let's get going.", completion = "We did it, {name}! At terrible cost... but victory is ours.\n\nThis keep could serve well as a home for me and my pack, though we tend to prefer more natural habitats.\n\nIt may be best to leave it as a reminder of Godfrey's betrayal and of the Bloodfang warriors that died here in battle.", objectives = "Kill Lord Godfrey.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27969] = { id = 27969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make Yourself Useful", description = "Gobbles vill be sorely missed, but zhe mission must not suffer.\n\nPerhaps zhere is somezhink you can do to redeem yourself.\n\nTake vone of zhe uniforms you recovered. Vhile vearink it, my vorkers vill not behave so... aggressively.\n\nLately, zheir morale has been a bit lackink. Some of zhe vorkers are refusing to perform zheir labors.\n\nAuch, zhe audacity!\n\nFind zhese lazy imbeciles and convince zhem zhat zhey must get to vork... or else!", completion = "Vell done, {class}.\n\nZhere may be hope for you yet.", objectives = "Commander Schnottz wants you to persuade 6 Slacking Laborers to get to work.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27970] = { id = 27970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain P. Harris", description = "The Cape of Lost Hope has been a sore in our side for weeks here on Tol Barad.  Half of our supply ships end up on the rocks down there.\n\nTo make matters worse, it's been overrun by a gang of undead sailors.  We have tried thinning the ranks, but they just seem to keep coming back.  Our last resort is to try and take out the captain that they report to.  You should be able to find him on a ship, just off the shoreline.\n\nOh, and I hope you are not too scared of sharks.", completion = "You did it!  Maybe we can finally get some ships into port now.  Thank you {name}.", objectives = "You have been tasked with killing Captain P. Harris at the Cape of Lost Hope. The Cape of Lost Hope can be found northwest of here, along the coast. Just look for the shipwrecks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27971] = { id = 27971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rattling Their Cages", description = "We have been having issues with the undead down at the Cape of Lost Hope for a while now.  Every time a new ship wrecks, they end up getting more undead to join their ranks.\n\nCan you do us a favor and thin out the ranks up there?  I know you won't be able to kill them all, but anything you can do will help at this point.\n\nKeep an eye out for horde, we have been getting reports of them ambushing the beach lately.", completion = "Nice work on the undead up there {name}.  We really appreciate the help.", objectives = "Camp Coordinator Brack has asked you to kill 8 Shipwrecked Sailors at the Cape of Lost Hope. The cape is located due northwest of here, on the beach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27972] = { id = 27972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boosting Morale", description = "Morale is low these days, {name}.  We make every effort we can to keep the troops in high spirits but we are running low on our main supply of morale booster... rum.\n\nI have been getting reports from our infantry to the south that the shipwrecks on the Cape of Lost Hope still have a good supply of southsea rum in their wrecked hulls.  Can you head up there and investigate?\n\nBring back any rum you can find.", progress = "Were you able to recover the rum?  I would try but I am deathly afraid of the water.  Not to mention that crazy shark.", completion = "This rum will really help us out, {name}.  They might not feel great in the morning but at least they will go to sleep happy.", objectives = "You have been asked to recover 6 Barrels of Southsea Rum from the shipwrecks on the Cape of Lost Hope. The cape can be found north of here, along the coast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27973] = { id = 27973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Watch Out For Splinters!", description = "Have you been over to the Wellson Shipyard yet, {name}?  Best to stay away from there unless you have a good reason to venture in.  Unfortunately, that is exactly what I need you to do.\n\nYou see, we have been short on supplies ever since we recaptured the island.  That ghost ridden shipyard is overflowing with lumber but every time we send an escort to recover the lumber, they never make it back.\n\nCan you help us out?", progress = "Did the ghosts scare you off?", completion = "I didn't think you would be able to do it, {name}.  You are just full of surprises aren't you?", objectives = "Sergeant Gray has asked you to recover 15 pieces of Shipyard Lumber from the Wellson Shipyard. The lumber can be recovered from the ghosts in the shipyard or found lying around the premises. The shipyard can be found northwest of here, on the coast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27974] = { id = 27974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Land is Our Land", description = "Did you think that a handful of worgen vermin could stop me? Hah!\n\nShadowfang Keep was part of the Lordaeron kingdom in life, so it is quite fitting that it should belong to the Forsaken in death. Godfrey and his accomplices are minor obstacles at best, and of course we're all happy to take them out for their treachery against the Dark Lady.\n\nAshbury has positioned himself near the front of the keep, leaving him wide open to attack. Start us out on the right foot, would you?", progress = "Don't test my patience and good will.", completion = "Ah, very well done! They've gotten a hold of powerful allies, but clearly nothing a {class}-champion of the Banshee Queen can't handle!", objectives = "Kill Baron Ashbury.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27975] = { id = 27975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Foreman Wellson", description = "Foreman Wellson has been a pain in our side since we got here.  His shipyard holds a large amount of supplies that would be extremely useful to us... if we could get to them.\n\nHe keeps a close watch over his minions and makes it very difficult for us to get a foothold on the shipyard.  I need you to take out Wellson for good this time.  Be careful {name}, we have been receiving reports of filthy Horde all around the area.", completion = "Great work {name}.  I will report your efforts to our highest in command immediately.", objectives = "Kill Foreman Wellson at the Wellson Shipyard. The shipyard can be found northwest of here, on the western coast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27976] = { id = 27976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curse These Fat Fingers", description = "Unfortunately, I can't dish out the beats like I used to, due to this here fat finger problem.  Ye see, the climate out here combined with the lack o' air pressure makes me fingers expand.  They're like gigantic Thelsamar Blood Sausages, they are...\n\nYe're gonna have to carry out me orders of business and what have ye.\n\nFirst on me agenda: Poundin' the livin' daylights out o' the heavy war golems o' the Gorge.  Get crackin'.", completion = "Ye're a good lad, ye are. I got ye a lil' present fer yer troubles.", objectives = "Kill 12 Heavy War Golems.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27977] = { id = 27977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recon Essentials", description = "We used to have more stuff around here.  I think there was a spyglass somewhere nearby, along with a smithing tuyere.\n\nI'm pretty certain that they've been stolen by Dark Iron dwarves.  Yes, I know that I'm a Dark Iron dwarf!  I'm talking about the bad ones that live down in that gorge.\n\nYou'd best check the steamsmiths that work just south of here.  They'd be most likely to use tools like these.", progress = "If you're here for the reward, you're gonna have to give me the stolen goods.", completion = "Fantastic work!", objectives = "Find and return the Smithing Tuyere and Lookout's Spyglass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27978] = { id = 27978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ghostbuster", description = "See that hill just beyond our base camp?  That's Largo's Overlook and it's not a fun place to setup camp next to.  We have been dealing with those spirits and spectres ever since we setup base camp.\n\nCan you head up there and let them know we don't plan on leaving anytime soon?  A few good kills on their ranks should put them in line.\n\nThanks for your help on this, {name}.", progress = "Who's afraid of ghosts?  Not me.  Well, maybe in the dark.", completion = "Great work, {name}!  We should not hear from the ghosts again anytime soon.", objectives = "Kill 14 ghosts of any type at Largo's Overlook, just northeast of base camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27979] = { id = 27979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Ministry", description = "I got one more assignment for ye.  This one comes straight down from the Overseer himself.  Seems he was pretty shook up once he heard about that \"Archduke\" ye discovered.\n\nHe's asked for us to hunt down three Twilight ministers that work over in Firewatch Ridge, to the west.  Kiyuubi, Letherio, and Finister are their names, and they each carry some sort o' special rock.  Combine all three and bring 'em back here.\n\nListen, when the Overseer gives orders, ye don't ask questions.  Ye just do it.", progress = "Ye got the thing?", completion = "<Hansel weighs the stone in his hands.>\n\nThis thing is strange, {name}.  I don't know what to make of it.  It ain't natural, that's for sure.", objectives = "Obtain Kiyuubi's Spherule, Letherio's Spherule, and Finister's Spherule, then combine them into a Twilight Tripetricine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27980] = { id = 27980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spiders Have to Go", description = "Normal-size spiders, I can handle.\n\nGiant glassweb spiders make me uncomfortable, but they're far enough away that I don't worry too much.\n\nBut lava spiders?  <Lolo shudders.>  Lava spiders are SCARY.  They're enormous spiders.  That live in LAVA.\n\nI just got paid for my last week of work, and I'll pay you well to kill those things.  You'll find 'em all over Searing Gorge.", completion = "There's no way you coulda killed all the spiders in the gorge, but you definitely made a dent.\n\nFine, here's what I promised ya.  Don't spend it all in one place.  Unless it's at Thorium Point.", objectives = "Slay 9 Lava Spiders within Searing Gorge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27981] = { id = 27981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heat That Just Don't Quit", description = "We smith, we smelt, we roast up whatever spider meat we can get.  Bush chicken if we're lucky.  Point is, all o' this work means we need lots and lots of fire.\n\nGood thing we're smack dab in the middle of firetown.\n\nO' course, the best fire comes from the elementals.  You'll find 'em all over Searing Gorge, but always near lava.  Here, take these flasks and use 'em on the elementals.\n\nOh, did I mention the elementals gotta be alive when you gather your sample?", progress = "Oilfist says he's gonna have us makin' firebombs soon.  All the more need for those flasks.", completion = "Yeeeeeeowch!  Don't just go puttin' this stuff into a dwarf's open hand.  This stuff is burnin' up!\n\nNow me hands are gonna get even more swollen...", objectives = "Obtain 10 Filled Furnace Flasks. You must use the Furnace Flasks on living elementals within Searing Gorge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27982] = { id = 27982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Collars", description = "Have ye seen the ridiculous necklaces those Twilight's Hammer cultists all wear?  The gems on those things are bigger than Hansel's fist!\n\nA few hamburger-sized jewels like that, and Burninate over there could really push his blacksmithing business to the next level.  Fetch those collars, and he'll make it worth your while.", progress = "A ruby-hilted hammer... it has a nice ring to it.", completion = "Hmm... the gems looked... sparklier from afar.  Up close, they look kind of dingy.\n\nAh well!  A little spit and polish should do the trick, and if not, I can use 'em to practice my disenchanting.", objectives = "Obtain 20 Twilight Collars.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27983] = { id = 27983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunk's Adventure: Cranky Little Dwarfs", description = "What you doing?  Why you kill?\n\nYou need to get things from dwarfs?  Ah, Lunk understand.  Lunk have a better way.\n\nListen: you go fight dwarf, but do not kill!  Just fight until dwarf get tired.  Then Lunk will help dwarf fall asleep.  Dwarfs probably just cranky because they don't get sleep.\n\nCome on!  Trust Lunk.", objectives = "Weaken 7 Dark Iron Steamsmiths so Lunk can help them fall asleep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27984] = { id = 27984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunthistle's Tale", description = "Will you assist me, mortal? Hear my tale.", progress = "Allow me to finish my story.", completion = "I have accepted my fate here in this cage, but the prayer must be found.", objectives = "Hear Zamael tell his tale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27985] = { id = 27985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prayer to Elune", description = "Will you assist me, mortal?  Will you find the prayer to Elune?\n\nAs I stated, the prayer was etched onto a golden tablet.  I believe they hold it within one of their vile chests, near the entrance to their cave at the bottom of the ridge.\n\nIf you do recover my prayer, don't bring it back to me.  Instead, take the time to read through it.\n\nAbsolution may be asking too much, based on the sins I've committed.  But that won't stop me from holding out hope.You will learn:", objectives = "Find and read the Prayer to Elune.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27986] = { id = 27986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In the Hall of the Mountain-Lord", description = "The Thorium Brotherhood doesn't maintain a militia - just a few guards, and me, and that's it.  If we're to successfully strike against the Dark Irons of the gorge, we're gonna need help.\n\nMountain-Lord Rendan sits atop that tower across the gorge, to our south.  He doesn't consort with Twilight folks or fire elementals, but he hasn't joined the brotherhood either.  Maybe it's time we paid him a visit.  With his help, we might just stand a chance.", completion = "And who might you be?\n\nAh, an emissary from the Thorium Brotherhood.  They're looking for my support?  Fine, I might be willin' to help out...\n\n...for a price.", objectives = "Speak with Mountain-Lord Rendan at Iron Summit in Searing Gorge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27987] = { id = 27987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cannonball!", description = "Largo and his minions have been stealing our supplies ever since we setup camp here.  It's frustrating to say the least.\n\nWe have heard reports that he is stockpiling cannonballs in the towers overlooking the water up on his overlook.  Can you head up there and try to recover some of them for us?\n\n{name}, don't forget to keep a watch out for horde too.", progress = "Did you find the cannonballs?", completion = "Good job on the recovery effort {name}. These cannonballs should last us a while.", objectives = "You need to recover 4 Stacks of Cannonballs from Largo's Overlook for Sergeant Gray. You can find Largo's Overlook just northeast of the base camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27988] = { id = 27988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plague...Plague Everywhere!", description = "The best part about this plague is that even when it visually fades away, the remaining residue is still quite potent! However, we still have an enormous area to cover before we're done, with plenty of Godfrey's defenses in the way.\n\nIt appears that the spirits that served Baron Silverlaine and Commander Springvale in life now guard them in death, and Godfrey is using them to deter us. Show them all the iron will of the Forsaken!", progress = "A couple bodiless spirits aren't going to best you, are they?", completion = "Cromush has both a thick skull and a fool's brain, and we'll use that to our advantage. By the time anybody finds out about the plague's true potency, it'll be far too late.\n\nThank you for keeping quiet during his tirade. I promise you won't regret it.", objectives = "Kill Baron Silverlaine and Commander Springvale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
